                }
            },
            required: ["methodology", "prd"]
        };

        return await this.executeStep<StepResult_PRD>(prompt, schema, [], onStream);
    }

    // --- STEP: STRATEGIC ROADMAP ---
    async generateRoadmap(feedback: string | undefined, onStream: (t: string) => void): Promise<StepResult_Roadmap> {
        const feedbackPrompt = feedback ? `USER INTERVENTION: "${feedback}". Adjust Roadmap.` : "Generate Strategic Roadmap.";

        const prompt = `
            ${feedbackPrompt}
            STEP: STRATEGIC PRODUCT ROADMAP.
            Act as an Executive Product Leader (CPO/VP).
            Create a roadmap mapping the PRD features (or derived initiatives if PRD is implicit) to horizons (Now, Next, Later).

            Focus on OUTCOMES (Goals/Themes).
            Determine status, ownership, dependencies, and success metrics for each item.

            Output JSON.
        `;

        const roadmapItemSchema: Schema = {
            type: Type.OBJECT,
            properties: {
                id: { type: Type.STRING },
                initiative: { type: Type.STRING },
                description: { type: Type.STRING },
                horizon: { type: Type.STRING, enum: ['Now', 'Next', 'Later'] },
                owner: { type: Type.STRING },
                status: { type: Type.STRING, enum: ['Planned', 'In Progress', 'Discovery', 'Shipped'] },
                dependencies: { type: Type.ARRAY, items: { type: Type.STRING } },
                successMetric: { type: Type.STRING }
            },
            required: ["initiative", "horizon", "status", "owner"]
        };

        const schema: Schema = {
            type: Type.OBJECT,
            properties: {
                methodology: { type: Type.STRING },
                roadmap: {
                    type: Type.OBJECT,
                    properties: {
                        vision: { type: Type.STRING },
                        goals: { type: Type.ARRAY, items: { type: Type.STRING } },
                        themes: { type: Type.ARRAY, items: { type: Type.STRING } },
                        items: { type: Type.ARRAY, items: roadmapItemSchema }
                    },
                    required: ["vision", "goals", "themes", "items"]
                }
            },
            required: ["methodology", "roadmap"]
        };

        return await this.executeStep<StepResult_Roadmap>(prompt, schema, [], onStream);
    }

    // --- STEP: TECHNICAL ARCHITECTURE ---
    async generateTechArchitecture(feedback: string | undefined, onStream: (t: string) => void): Promise<StepResult_TechArch> {
        const feedbackPrompt = feedback 
            ? `USER INTERVENTION: "${feedback}". \nCRITICAL INSTRUCTION: You MUST regenerate the 'architecture' object to reflect this feedback. Update nodes, flows, or descriptions accordingly. Explicitly acknowledge the change in the 'methodology' field using the [CORRECTION] tag.` 
            : "Generate Technical Architecture.";

        const prompt = `
            ${feedbackPrompt}
            STEP: TECHNICAL SOLUTION ARCHITECTURE.
            Act as a Solution Architect.
            Based on the Themes, Pain Points and Opportunities identified in the research, propose a technical system architecture.
            Design flat, modern, minimalistic system flows.
            Define the Nodes (Users, Systems, Databases) and Flows.

            If specific user personas are missing, infer user roles from the context.

            Output JSON.
        `;

        const schema: Schema = {
            type: Type.OBJECT,
            properties: {
                methodology: { type: Type.STRING },
                architecture: {
                    type: Type.OBJECT,
                    properties: {
                        overview: { type: Type.STRING },
                        nodes: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    id: { type: Type.STRING },
                                    label: { type: Type.STRING },
                                    type: { type: Type.STRING, enum: ['User', 'System', 'Database', 'External API', 'Security'] },
                                    description: { type: Type.STRING }
                                },
                                required: ["id", "label", "type"]
                            }
                        },
                        flows: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    fromId: { type: Type.STRING },
                                    toId: { type: Type.STRING },
                                    action: { type: Type.STRING },
                                    protocol: { type: Type.STRING }
                                },
                                required: ["fromId", "toId", "action"]
                            }
                        },
                        securityConsiderations: { type: Type.ARRAY, items: { type: Type.STRING } }
                    },
                    required: ["overview", "nodes", "flows"]
                }
            },
            required: ["methodology", "architecture"]
        };

        const result = await this.executeStep<StepResult_TechArch>(prompt, schema, [], onStream);

        // --- Generate Diagram Image ---
        if (result.architecture) {
            const nodesList = result.architecture.nodes.map(n => n.label).join(", ");
            const flowsList = result.architecture.flows.map(f => `${f.fromId} to ${f.toId} (${f.action})`).join("; ");
            const imgPrompt = `A gorgeous, professional system flow diagram visualization. White background. Clean vector lines. Nodes: ${nodesList}. Flows: ${flowsList}. Technical architecture style. No photorealism. Infographic style.`;

            try {
                const diagramUrl = await generateImage(imgPrompt, "16:9");
                result.architecture.diagramUrl = diagramUrl;
            } catch (e) {
                console.warn("Failed to generate architecture diagram image", e);
            }
        }

        return result;
    }

    // --- STEP 3.5: DECK STRUCTURE ---
    async generateDeckStructure(feedback: string | undefined, recommendations: StrategicRecommendation[] | undefined, onStream: (t: string) => void): Promise<StepResult_Structure> {
        const feedbackPrompt = feedback 
            ? `USER INTERVENTION: "${feedback}". Adjust outline.` 
            : "Plan the Strategy Deck.";

        let recsContext = "";
        if (recommendations && recommendations.length > 0) {
            recsContext = `APPROVED RECOMMENDATIONS: ${JSON.stringify(recommendations)}. Ensure the deck structure specifically includes slides to present these recommendations.`;
        }

        const prompt = `
            ${feedbackPrompt}
            ${recsContext}
            STEP: PRESENTATION ARCHITECTURE.
            Create a detailed structure for the final presentation answering the Research Goal: "${this.goal}".
            RULES: No length limit. Create 'storyArc'.
            Output JSON.
        `;

        const schema: Schema = {
            type: Type.OBJECT,
            properties: {
                methodology: { type: Type.STRING },
                storyArc: { type: Type.STRING },
                slides: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            slideNumber: { type: Type.INTEGER },
                            layout: { type: Type.STRING, enum: ['TITLE_SLIDE', 'SECTION_HEADER', 'CONTENT_SPLIT_RIGHT', 'CONTENT_SPLIT_LEFT', 'FULL_BLEED_IMAGE', 'TYPOGRAPHY_QUOTE'] },
                            title: { type: Type.STRING },
                            rationale: { type: Type.STRING }
                        },
                        required: ["slideNumber", "layout", "title", "rationale"]
                    }
                }
            },
            required: ["methodology", "storyArc", "slides"]
        };

        return await this.executeStep<StepResult_Structure>(prompt, schema, [], onStream);
