    // --- STEP 4: NARRATIVE & CONTENT ---
    async generateNarrative(
        structure: StepResult_Structure, 
        recommendations: StrategicRecommendation[] | undefined,
        feedback: string | undefined, 
        onStream: (t: string) => void
    ): Promise<StepResult_Narrative> {

        const slidesContext = JSON.stringify(structure.slides.map(s => ({ num: s.slideNumber, title: s.title, layout: s.layout, rationale: s.rationale })));

        let recsContext = "";
        if (recommendations && recommendations.length > 0) {
            recsContext = `CONTEXT: The user has ALREADY approved these recommendations: ${JSON.stringify(recommendations)}. Use them to inform the narrative/slides. Do NOT generate new ones.`;
        }

        const feedbackPrompt = feedback ? `USER INTERVENTION: "${feedback}".` : "Outline approved.";

        const prompt = `
            ${feedbackPrompt}
            ${recsContext}
            STEP: NARRATIVE & CONTENT.
            INPUT STRUCTURE: ${slidesContext}

            TASKS:
            1. Generate Video Script scenes.
            2. Generate Slides Content, Narrative, and VISUAL PROMPTS.

            Output JSON.
        `;

        const schema: Schema = {
            type: Type.OBJECT,
            properties: {
                methodology: { type: Type.STRING },
                videoScript: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            sceneNumber: { type: Type.INTEGER },
                            visualDescription: { type: Type.STRING },
                            audioNarration: { type: Type.STRING },
                            durationSeconds: { type: Type.INTEGER },
                            tags: { type: Type.ARRAY, items: { type: Type.STRING } },
                            personaRef: { type: Type.STRING },
                            quote: { type: Type.STRING },
                            visualPrompt: { type: Type.STRING }
                        },
                        required: ["sceneNumber", "visualDescription", "audioNarration", "quote", "visualPrompt"]
                    }
                },
                slides: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            slideNumber: { type: Type.INTEGER },
                            layout: { type: Type.STRING, enum: ['TITLE_SLIDE', 'SECTION_HEADER', 'CONTENT_SPLIT_RIGHT', 'CONTENT_SPLIT_LEFT', 'FULL_BLEED_IMAGE', 'TYPOGRAPHY_QUOTE'] },
                            title: { type: Type.STRING },
                            content: { type: Type.ARRAY, items: { type: Type.STRING } },
                            narrative: { type: Type.STRING },
                            speakerNotes: { type: Type.STRING },
                            visualPrompt: { type: Type.STRING },
                            quote: { type: Type.STRING }
                        },
                        required: ["slideNumber", "layout", "title", "content", "narrative", "visualPrompt", "quote"]
                    }
                }
            },
            required: ["methodology", "videoScript", "slides"]
        };

        const result = await this.executeStep<StepResult_Narrative>(prompt, schema, [], onStream);

        // Inject Default Styles
        const slidesWithStyle = (result.slides || []).map(slide => ({
            ...slide,
            style: { ...DEFAULT_STYLE }
        }));

        return { ...result, slides: slidesWithStyle };
    }

    // --- STEP 5: VISUALIZATION ---
    async visualizeNarrative(
        narrativeData: StepResult_Narrative, 
        personas: Persona[], 
        recommendations: StrategicRecommendation[],
        outputs: OutputOption[],
        onStatus: (s: string) => void, 
        onStream?: (t: string) => void
    ): Promise<StepResult_Final> {

        const scriptWithImages: ScriptScene[] = [];
        const personaMap = new Map<string, string>();
        personas.forEach(p => { if (p.imageUrl) personaMap.set(p.name, p.imageUrl); });

        const pushEvent = (type: string, content: string) => {
            if (onStream) {
                onStream(` "[methodology]": "[${type}] ${content} [${type}]" `); 
            }
        };

        pushEvent("PHASE", "Starting Visual Generation Sequence");

        // 1. Video Script Images (Only if Video Script selected)
        if (outputs.includes('VIDEO_SCRIPT')) {
            onStatus("Visualizing Storyboard...");
            for (let i = 0; i < narrativeData.videoScript.length; i++) {
                const scene = narrativeData.videoScript[i];
                onStatus(`Visualizing Scene ${i+1}/${narrativeData.videoScript.length}...`);

                const descSnippet = scene.visualDescription ? scene.visualDescription.substring(0, 30) : "Scene";
                pushEvent("INSIGHT", `Generating visual for Scene ${i+1}: ${descSnippet}...`);

                let refImage = undefined;
                if (scene.personaRef && personaMap.has(scene.personaRef)) {
                    refImage = personaMap.get(scene.personaRef);
                }
                const promptToUse = scene.visualPrompt || scene.visualDescription;
                const url = await generateImage(promptToUse, "16:9", refImage);
                scriptWithImages.push({ ...scene, imageUrl: url, videoStatus: 'idle', imageStatus: 'idle' });
            }
        }

        // 2. Strategy Deck Images (Only if Deck selected)
        let slidesWithImages: Slide[] = [];
        if (outputs.includes('STRATEGY_DECK')) {
            onStatus("Visualizing Strategy Deck...");
            pushEvent("PHASE", "Generating Strategy Deck Visuals");

            slidesWithImages = await Promise.all((narrativeData.slides || []).map(async (slide, idx) => {
                let imageUrl = undefined;
                let aspectRatio = "16:9";
                if (slide.layout === 'CONTENT_SPLIT_RIGHT' || slide.layout === 'CONTENT_SPLIT_LEFT') {
                    aspectRatio = "1:1";
                }

                const isInfographic = slide.visualPrompt && (
                    slide.visualPrompt.toLowerCase().includes("infographic") || 
                    slide.visualPrompt.toLowerCase().includes("visualization") || 
                    slide.visualPrompt.toLowerCase().includes("chart")
                );

                if (slide.layout === 'FULL_BLEED_IMAGE' || slide.layout === 'SECTION_HEADER' || isInfographic) {
                     onStatus(`Generating High-Fidelity Slide Visual ${idx+1}...`);
                     pushEvent("INSIGHT", `Creating high-fidelity asset for Slide ${idx+1} (${slide.layout})`);
                     imageUrl = await generateImage(slide.visualPrompt, aspectRatio);
                } else {
                     if (scriptWithImages.length > 0) {
                         const sceneIndex = Math.floor((idx / narrativeData.slides.length) * scriptWithImages.length);
                         imageUrl = scriptWithImages[sceneIndex]?.imageUrl;
                     }
                     if (!imageUrl) {
                        imageUrl = await generateImage(slide.visualPrompt, aspectRatio);
                     }
                }
                return { ...slide, imageUrl: imageUrl, imageStatus: 'idle' as const };
            }));
        }

        pushEvent("PHASE", "Visualization Complete");

        return { 
            methodology: narrativeData.methodology,
            videoScript: scriptWithImages, 
            slides: slidesWithImages,
            recommendations: recommendations // Pass through the approved ones
        };
    }


    // --- GENERIC EXECUTOR ---
    private async executeStep<T>(prompt: string, schema: Schema, parts: any[] = [], onStream: (t: string) => void): Promise<T> {
        const result = await withRetry<any>(() => this.chatSession.sendMessageStream({
            message: [...parts, { text: prompt }],
            config: {
                responseMimeType: "application/json",
                responseSchema: schema
            }
        }), 3, 2000, "GenAI Step Execution");

        let fullText = "";
        for await (const chunk of result) {
            fullText += (chunk as GenerateContentResponse).text;
            onStream(fullText);
        }

        try {
            return JSON.parse(fullText) as T;
        } catch (e) {
            console.error("JSON Parse Error", e);
            throw new Error("Failed to parse Gemini response");
        }
    }
}

