    const [researchGoal, setResearchGoal] = useState("Identify emerging needs in the remote work sector.");
    const [analysisApproach, setAnalysisApproach] = useState("Standard Ethnographic Analysis");
    const [streamingLog, setStreamingLog] = useState<string[]>([]);
    const [thinkingEvents, setThinkingEvents] = useState<ThinkingEvent[]>([]);
    const [savedProjects, setSavedProjects] = useState<SavedProject[]>([]);

    // State for Analysis Results (Intermediate & Final)
    const [result, setResult] = useState<AnalysisResult | null>(null);
    const [ingestionResult, setIngestionResult] = useState<any>(null);
    const [themesResult, setThemesResult] = useState<any>(null);
    const [personasResult, setPersonasResult] = useState<any>(null);
    const [structureResult, setStructureResult] = useState<any>(null);
    const [narrativeResult, setNarrativeResult] = useState<any>(null);
    const [journeyResult, setJourneyResult] = useState<any>(null);
    const [techResult, setTechResult] = useState<any>(null);
    const [prdResult, setPrdResult] = useState<any>(null);
    const [roadmapResult, setRoadmapResult] = useState<any>(null);
    const [recsResult, setRecsResult] = useState<any>(null);

    const sessionRef = useRef<GenAISession | null>(null);

    useEffect(() => {
        const saved = localStorage.getItem('nxt_saved_projects');
        if (saved) {
            try {
                setSavedProjects(JSON.parse(saved));
            } catch (e) {
                console.error("Failed to load saved projects", e);
            }
        }
    }, []);

    const handleStreamUpdate = (text: string) => {
        // Parse the text for specific tags [PHASE], [INSIGHT], [CORRECTION]
        const regex = /\[(PHASE|INSIGHT|CORRECTION|QUESTION|HYPOTHESIS)\] (.*?)(?=\[|$)/g;
        let match;
        while ((match = regex.exec(text)) !== null) {
            const type = match[1];
            const content = match[2].trim();
            // Check if this specific event content is already logged to avoid duplicates in the UI
            setThinkingEvents(prev => {
                const exists = prev.some(e => e.type === type && e.content === content);
                if (!exists) return [...prev, { type, content }];
                return prev;
            });
        }
    };

    const handleSaveProject = () => {
        if (!result) return;
        const newProject: SavedProject = {
            id: Date.now().toString(),
            name: researchGoal || "Untitled Project",
            createdAt: Date.now(),
            goal: researchGoal,
            approach: analysisApproach,
            selectedOutputs: selectedOutputs,
            result: result,
            ingestion: ingestionResult,
            themes: themesResult,
            personas: personasResult,
            journeyMap: journeyResult,
            techArch: techResult,
            prd: prdResult,
            roadmap: roadmapResult,
            recommendations: recsResult,
            structure: structureResult,
            narrative: narrativeResult
        };
        const updated = [newProject, ...savedProjects];
        setSavedProjects(updated);
        localStorage.setItem('nxt_saved_projects', JSON.stringify(updated));
        alert("Project saved locally!");
    };

    const loadProject = async (project: SavedProject) => {
        // Hydrate State
        setResearchGoal(project.goal);
        setAnalysisApproach(project.approach);
        setSelectedOutputs(project.selectedOutputs);

        setIngestionResult(project.ingestion);
        setThemesResult(project.themes);
        setPersonasResult(project.personas);
        setJourneyResult(project.journeyMap);
        setTechResult(project.techArch);
        setPrdResult(project.prd);
        setRoadmapResult(project.roadmap);
        setRecsResult(project.recommendations);
        setStructureResult(project.structure);
        setNarrativeResult(project.narrative);
        setResult(project.result);

        // Try to Re-ignite the session for potential edits (if key is available)
        if (process.env.API_KEY) { 
             sessionRef.current = new GenAISession(project.goal, project.approach, project.selectedOutputs);
             // We don't await this to keep UI snappy, but we trigger the context injection
             sessionRef.current.restore(project.ingestion, project.themes, project.personas, project.structure);
        }

        setAppState(AppState.SUCCESS);
    };

    const deleteProject = (id: string) => {
        const updated = savedProjects.filter(p => p.id !== id);
        setSavedProjects(updated);
        localStorage.setItem('nxt_saved_projects', JSON.stringify(updated));
    };

    const startAnalysis = async () => {
        if (!process.env.API_KEY) {
            if (window.aistudio && await window.aistudio.hasSelectedApiKey()) {
                // Good
            } else if (window.aistudio) {
                await window.aistudio.openSelectKey();
                // Race condition mitigation
                await new Promise(r => setTimeout(r, 1000));
            }
        }

        setAppState(AppState.ANALYZING);
        setThinkingEvents([]);
        sessionRef.current = new GenAISession(researchGoal, analysisApproach, selectedOutputs);

        try {
            // STEP 1: Ingestion
            setStatusMessage("Reading & Contextualizing...");
            setActiveStage(AnalysisStage.INGESTION);
            const ingestion = await sessionRef.current.ingestContext(files, handleStreamUpdate);
            setIngestionResult(ingestion);
            setStatusMessage("Context verification required."); // Update to remove '...' so modal unlocks
            // Wait for user approval via Checkpoint
        } catch (e) {
            console.error(e);
            setAppState(AppState.ERROR);
            setStatusMessage("Error during analysis. Please try again.");
            setActiveStage(AnalysisStage.IDLE); // Important: Close modal on error
        }
    };

    const handleCheckpointApproval = async (feedback?: string, modifiedData?: any, interventionLog?: string) => {
        if (!sessionRef.current) return;

        // Log user intervention explicitly to the history stream
        if (interventionLog) {
             setThinkingEvents(prev => [...prev, { type: 'INTERVENTION', content: interventionLog }]);
        } else if (feedback) {
             setThinkingEvents(prev => [...prev, { type: 'INTERVENTION', content: feedback }]);
        } else if (modifiedData) {
             setThinkingEvents(prev => [...prev, { type: 'INTERVENTION', content: "Manual Data Edits Applied" }]);
        }

        // CRITICAL UPDATE: If this is an approval (no feedback triggering regeneration),
        // we close the modal IMMEDIATELY to give instant responsiveness, while the async operations happen in background.
        // If feedback exists, we keep the modal open to show the "Regenerating..." state.
        if (!feedback) {
            setActiveStage(AnalysisStage.IDLE);
        }

        try {
            // IF EDITING FROM FINAL VIEW
            if (appState === AppState.SUCCESS) {
                console.log("Saving edits from Results View...", activeStage);
                if (modifiedData) {
                    if (activeStage === AnalysisStage.PERSONAS) {
                         setPersonasResult(modifiedData);
                         setResult((prev: any) => ({ ...prev, personas: modifiedData.personas }));
                         await sessionRef.current.updateContext("Personas", modifiedData);
                    } else if (activeStage === AnalysisStage.THEMES) {
                         setThemesResult(modifiedData);
                         setResult((prev: any) => ({ ...prev, themes: modifiedData.themes }));
                         await sessionRef.current.updateContext("Themes", modifiedData);
                    } else if (activeStage === AnalysisStage.JOURNEY_MAP) {
                         setJourneyResult(modifiedData);
                         setResult((prev: any) => ({ ...prev, journeyMap: modifiedData.stages }));
                         // Trigger image regeneration for diagram?
                         if (modifiedData.stages) {
                            const resultWithDiagram = await sessionRef.current.generateJourneyMap("Regenerate diagram only based on updated stages");
                             setJourneyResult((prev:any) => ({...prev, diagramUrl: resultWithDiagram.diagramUrl}));
                             setResult((prev: any) => ({ ...prev, journeyMap: modifiedData.stages, journeyMapDiagramUrl: resultWithDiagram.diagramUrl }));
                         }
                    } else if (activeStage === AnalysisStage.PRD) {
                        setPrdResult(modifiedData);
                        setResult((prev: any) => ({ ...prev, prd: modifiedData.prd }));
                    } else if (activeStage === AnalysisStage.ROADMAP) {
                        setRoadmapResult(modifiedData);
                        setResult((prev: any) => ({ ...prev, roadmap: modifiedData.roadmap }));
                    } else if (activeStage === AnalysisStage.TECH_ARCH) {
                        setTechResult(modifiedData);
                        setResult((prev: any) => ({ ...prev, techArchitecture: modifiedData.architecture }));
                        // Trigger image regeneration
                         if (modifiedData.architecture) {
                            const resultWithDiagram = await sessionRef.current.generateTechArchitecture("Regenerate diagram only");
                             setTechResult((prev:any) => ({...prev, architecture: {...prev.architecture, diagramUrl: resultWithDiagram.architecture.diagramUrl}}));
                             setResult((prev: any) => ({ ...prev, techArchitecture: { ...modifiedData.architecture, diagramUrl: resultWithDiagram.architecture.diagramUrl } }));
                         }
                    } else if (activeStage === AnalysisStage.RECOMMENDATIONS) {
                        setRecsResult(modifiedData);
                        setResult((prev: any) => ({ ...prev, recommendations: modifiedData.recommendations }));
                    } else if (activeStage === AnalysisStage.DECK_STRUCTURE) {
                        setStructureResult(modifiedData);
                        // No result update here usually unless we regenerate content
                    } else if (activeStage === AnalysisStage.NARRATIVE) {
                        setNarrativeResult(modifiedData);
                        // Trigger visual regen? For now just save text.
                    }
                }

                // If we didn't already close it above (unlikely in success edit flow, but for safety)
                if (feedback) setActiveStage(AnalysisStage.IDLE); 
                return;
            }

            // --- STANDARD LINEAR FLOW ---

            if (activeStage === AnalysisStage.INGESTION) {
                // Ingestion typically moves forward to Themes even with feedback
                setStatusMessage("Identifying Patterns...");
                const themes = await sessionRef.current.generateThemes(feedback, handleStreamUpdate);
                setThemesResult(themes);
                setStatusMessage("Themes Identified"); // Unlock modal
                setActiveStage(AnalysisStage.THEMES);
            } 
            else if (activeStage === AnalysisStage.THEMES) {
                // If modified themes, update context
                if (modifiedData) {
                    setThemesResult(modifiedData);
                    await sessionRef.current.updateContext("Themes", modifiedData);
                }

                // REGENERATION CHECK: If feedback provided, regenerate THEMES and stay
                if (feedback) {
                    setStatusMessage("Refining Themes...");
                    const themes = await sessionRef.current.generateThemes(feedback, handleStreamUpdate);
                    setThemesResult(themes);
                    setStatusMessage("Themes Refined");
                    return; // Stay on this stage
                }

                // Branch Logic based on selectedOutputs
                if (selectedOutputs.includes('PERSONAS')) {
                    setStatusMessage("Synthesizing Personas...");
                    const personas = await sessionRef.current.generatePersonas(themesResult, undefined, handleStreamUpdate, setStatusMessage);
                    setPersonasResult(personas);
                    setStatusMessage("Personas Generated"); // Unlock modal
                    setActiveStage(AnalysisStage.PERSONAS);
                } else {
                    // Skip to next relevant stage
                    advanceToNextStage();
                }
            } 
            else if (activeStage === AnalysisStage.PERSONAS) {
                 if (modifiedData) {
                    setPersonasResult(modifiedData);
                    await sessionRef.current.updateContext("Personas", modifiedData);
                }

                // REGENERATION CHECK
                if (feedback) {
                    setStatusMessage("Refining Personas...");
                    const personas = await sessionRef.current.generatePersonas(themesResult, feedback, handleStreamUpdate, setStatusMessage);
                    setPersonasResult(personas);
                    setStatusMessage("Personas Refined");
                    return;
                }

                advanceToNextStage();
            }
            // ... Handling other parallel branches ...
            else if (activeStage === AnalysisStage.JOURNEY_MAP) {
                if (modifiedData) { setJourneyResult(modifiedData); await sessionRef.current.updateContext("Service Blueprint", modifiedData); }
                if (feedback) {
                    setStatusMessage("Refining Blueprint...");
                    const map = await sessionRef.current.generateJourneyMap(feedback, handleStreamUpdate);
                    setJourneyResult(map);
                    setStatusMessage("Blueprint Refined");
                    return;
                }
                advanceToNextStage();
            }
            else if (activeStage === AnalysisStage.PRD) {
                if (modifiedData) { setPrdResult(modifiedData); await sessionRef.current.updateContext("PRD", modifiedData); }
                if (feedback) {
                    setStatusMessage("Refining PRD...");
                    const prd = await sessionRef.current.generatePRD(feedback, handleStreamUpdate);
                    setPrdResult(prd);
                    setStatusMessage("PRD Refined");
                    return;
                }
                advanceToNextStage();
            }
            else if (activeStage === AnalysisStage.ROADMAP) {
                if (modifiedData) { setRoadmapResult(modifiedData); await sessionRef.current.updateContext("Roadmap", modifiedData); }
                if (feedback) {
                    setStatusMessage("Refining Roadmap...");
                    const map = await sessionRef.current.generateRoadmap(feedback, handleStreamUpdate);
                    setRoadmapResult(map);
                    setStatusMessage("Roadmap Refined");
                    return;
                }
                advanceToNextStage();
            }
            else if (activeStage === AnalysisStage.TECH_ARCH) {
                 if (modifiedData) { setTechResult(modifiedData); await sessionRef.current.updateContext("Architecture", modifiedData); }
                 if (feedback) {
                    setStatusMessage("Refining Architecture...");
                    const arch = await sessionRef.current.generateTechArchitecture(feedback, handleStreamUpdate);
                    setTechResult(arch);
                    setStatusMessage("Architecture Refined");
                    return;
                }
                advanceToNextStage();
            }
            else if (activeStage === AnalysisStage.RECOMMENDATIONS) {
                 if (modifiedData) { setRecsResult(modifiedData); await sessionRef.current.updateContext("Recommendations", modifiedData); }
                 if (feedback) {
                    setStatusMessage("Refining Strategy...");
                    const recs = await sessionRef.current.generateRecommendations(feedback, handleStreamUpdate);
                    setRecsResult(recs);
                    setStatusMessage("Strategy Refined");
                    return;
                }
                advanceToNextStage();
            }
            // ... Final Assembly Stages ...
            else if (activeStage === AnalysisStage.DECK_STRUCTURE) {
                if (modifiedData) setStructureResult(modifiedData);

                if (feedback) {
                    setStatusMessage("Refining Structure...");
                    const struct = await sessionRef.current.generateDeckStructure(feedback, recsResult?.recommendations, handleStreamUpdate);
                    setStructureResult(struct);
                    setStatusMessage("Structure Refined");
                    return;
                }

                setStatusMessage("Drafting Narrative & Content...");

                // 1. Generate Narrative Content
                const narrative = await sessionRef.current.generateNarrative(modifiedData || structureResult, recsResult?.recommendations, undefined, handleStreamUpdate);
                setNarrativeResult(narrative);

                // 2. IMMEDIATE VISUALIZATION (SKIP Narrative Checkpoint)
                setStatusMessage("Generating High-Fidelity Assets...");
                const final = await sessionRef.current.visualizeNarrative(
                    narrative, 
                    personasResult?.personas || [], 
                    recsResult?.recommendations || [],
                    selectedOutputs,
                    setStatusMessage, 
                    handleStreamUpdate
                );

                // Consolidate everything into Final Result
                setResult({
                    methodology: final.methodology,
                    selectedOutputs: selectedOutputs,
                    themes: themesResult?.themes || [],
                    personas: personasResult?.personas || [],
                    videoScript: final.videoScript,
                    slides: final.slides,
                    recommendations: recsResult?.recommendations || [],
                    journeyMap: journeyResult?.stages,
                    journeyMapDiagramUrl: journeyResult?.diagramUrl,
                    techArchitecture: techResult?.architecture,
                    prd: prdResult?.prd,
                    roadmap: roadmapResult?.roadmap
                });
                setAppState(AppState.SUCCESS);
            }
            // Narrative stage block effectively unused for standard flow but kept for safety
            else if (activeStage === AnalysisStage.NARRATIVE) {
                if (modifiedData) setNarrativeResult(modifiedData);

                setStatusMessage("Generating High-Fidelity Assets...");

                const final = await sessionRef.current.visualizeNarrative(
                    modifiedData || narrativeResult, 
                    personasResult?.personas || [], 
                    recsResult?.recommendations || [],
                    selectedOutputs,
                    setStatusMessage, 
                    handleStreamUpdate
                );

                setResult({
                    methodology: final.methodology,
                    selectedOutputs: selectedOutputs,
                    themes: themesResult?.themes || [],
                    personas: personasResult?.personas || [],
                    videoScript: final.videoScript,
                    slides: final.slides,
                    recommendations: recsResult?.recommendations || [],
                    journeyMap: journeyResult?.stages,
                    journeyMapDiagramUrl: journeyResult?.diagramUrl,
                    techArchitecture: techResult?.architecture,
                    prd: prdResult?.prd,
                    roadmap: roadmapResult?.roadmap
                });
                setAppState(AppState.SUCCESS);
            }
        } catch (e) {
            console.error(e);
            setAppState(AppState.ERROR);
        }
    };

    const advanceToNextStage = async () => {
        // Simple state machine to determine next step based on `selectedOutputs` and what's already done

        // 1. Journey Map
        if (selectedOutputs.includes('JOURNEY_MAP') && !journeyResult) {
            // Note: If advanceToNextStage is called from handleCheckpointApproval, activeStage might have been cleared above.
            // If we need to process, we update status.

            setStatusMessage("Mapping Service Blueprint...");
            const map = await sessionRef.current?.generateJourneyMap(undefined, handleStreamUpdate);
            setJourneyResult(map);
            setStatusMessage("Blueprint Ready"); // Unlock
            setActiveStage(AnalysisStage.JOURNEY_MAP);
            return;
        }

        // 2. PRD
        if (selectedOutputs.includes('PRD') && !prdResult) {
            setStatusMessage("Defining Product Requirements...");
            const prd = await sessionRef.current?.generatePRD(undefined, handleStreamUpdate);
            setPrdResult(prd);
            setStatusMessage("PRD Drafted"); // Unlock
            setActiveStage(AnalysisStage.PRD);
            return;
        }

        // 3. Roadmap (Dependencies: PRD)
        if (selectedOutputs.includes('ROADMAP') && !roadmapResult) {
            setStatusMessage("Planning Strategic Roadmap...");
            const map = await sessionRef.current?.generateRoadmap(undefined, handleStreamUpdate);
            setRoadmapResult(map);
            setStatusMessage("Roadmap Drafted"); // Unlock
            setActiveStage(AnalysisStage.ROADMAP);
            return;
        }

        // 4. Tech Arch
        if (selectedOutputs.includes('TECH_ARCH') && !techResult) {
            setStatusMessage("Architecting Solution...");
            const arch = await sessionRef.current?.generateTechArchitecture(undefined, handleStreamUpdate);
            setTechResult(arch);
            setStatusMessage("Architecture Drafted"); // Unlock
            setActiveStage(AnalysisStage.TECH_ARCH);
            return;
        }

        // 5. Recommendations
        if (selectedOutputs.includes('STRATEGIC_RECS') && !recsResult) {
            setStatusMessage("Formulating Strategy...");
            const recs = await sessionRef.current?.generateRecommendations(undefined, handleStreamUpdate);
            setRecsResult(recs);
            setStatusMessage("Strategy Drafted"); // Unlock
            setActiveStage(AnalysisStage.RECOMMENDATIONS);
            return;
        }

        // 6. Deck Structure (If Deck or Script selected)
        if ((selectedOutputs.includes('STRATEGY_DECK') || selectedOutputs.includes('VIDEO_SCRIPT')) && !structureResult) {
            setStatusMessage("Architecting Presentation...");
            const struct = await sessionRef.current?.generateDeckStructure(undefined, recsResult?.recommendations, handleStreamUpdate);
            setStructureResult(struct);
            setStatusMessage("Structure Drafted"); // Unlock
            setActiveStage(AnalysisStage.DECK_STRUCTURE);
            return;
        }

        // If we are here, we are done with intermediate steps or just have a subset that doesn't include deck
        // Force a final assembly if no deck/script
        if (!selectedOutputs.includes('STRATEGY_DECK') && !selectedOutputs.includes('VIDEO_SCRIPT')) {
             setResult({
                methodology: "Direct Assembly",
                selectedOutputs: selectedOutputs,
                themes: themesResult?.themes || [],
                personas: personasResult?.personas || [],
                recommendations: recsResult?.recommendations || [],
                journeyMap: journeyResult?.stages,
                journeyMapDiagramUrl: journeyResult?.diagramUrl,
                techArchitecture: techResult?.architecture,
                prd: prdResult?.prd,
                roadmap: roadmapResult?.roadmap
            });
            setAppState(AppState.SUCCESS);
        }
    };

    const toggleOutput = (opt: OutputOption) => {
        if (selectedOutputs.includes(opt)) {
            setSelectedOutputs(selectedOutputs.filter(o => o !== opt));
        } else {
            setSelectedOutputs([...selectedOutputs, opt]);
        }
    };

    return (
        <div className="min-h-screen bg-[var(--bg-primary)] text-[var(--text-primary)] transition-colors duration-300 font-sans selection:bg-[var(--nxt-pink)] selection:text-white">

            {/* Header */}
            {appState !== AppState.SUCCESS && (
                <header className="fixed top-0 w-full z-40 bg-[var(--bg-secondary)]/80 backdrop-blur-md border-b border-[var(--border-primary)]">
                    <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
                        <Logo />
                    </div>
                </header>
            )}

            <main className={`transition-all duration-500 ${appState !== AppState.SUCCESS ? 'pt-24 px-6' : ''}`}>

                {/* IDLE STATE */}
                {appState === AppState.IDLE && (
                    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="max-w-3xl mx-auto space-y-12 pb-20">
                        <div className="text-center space-y-4">
                            <h1 className="text-5xl font-black tracking-tight leading-tight">
                                Humans in Control <span className="gradient-text">Research System</span>
                            </h1>
                            <p className="text-xl text-[var(--text-secondary)] max-w-2xl mx-auto font-light">
                                Upload unstructured data. Define your lens. <br/>
                                Generate <span className="font-semibold">verified</span> personas, strategies, and storyboards.
                            </p>
                        </div>

                        <div className="bg-[var(--card-bg)] p-8 rounded-2xl border border-[var(--border-primary)] shadow-xl space-y-8">
                            {/* Inputs */}
                            <div className="space-y-4">
                                <div>
                                    <label className="text-xs font-bold uppercase tracking-widest text-[var(--text-tertiary)] mb-2 block">Research Goal</label>
                                    <input 
                                        type="text" 
                                        value={researchGoal}
                                        onChange={(e) => setResearchGoal(e.target.value)}
                                        className="w-full bg-[var(--input-bg)] border border-[var(--border-primary)] p-4 rounded-xl text-lg focus:ring-2 focus:ring-[var(--nxt-pink)] outline-none transition-all shadow-inner"
                                        placeholder="e.g. Understand the barriers to EV adoption..."
                                    />
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                     <div>
                                        <label className="text-xs font-bold uppercase tracking-widest text-[var(--text-tertiary)] mb-2 block">Analysis Methodology/Approach</label>
                                        <input
                                            type="text"
                                            value={analysisApproach}
                                            onChange={(e) => setAnalysisApproach(e.target.value)}
                                            className="w-full bg-[var(--input-bg)] border border-[var(--border-primary)] p-4 rounded-xl text-sm outline-none shadow-inner focus:ring-2 focus:ring-[var(--nxt-pink)] transition-all"
                                            placeholder="e.g. Standard Ethnographic Analysis, JTBD, Behavioral Economics..."
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* Outputs Selection */}
                            <div>
                                <label className="text-xs font-bold uppercase tracking-widest text-[var(--text-tertiary)] mb-3 block">Required Outputs</label>
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                                    {Object.keys(METHODOLOGY_INFO).map((key) => (
                                        <div key={key} className="relative group">
                                            <button 
                                                onClick={() => toggleOutput(key as OutputOption)}
                                                className={`w-full p-3 rounded-lg border text-xs font-bold transition-all h-full flex flex-col items-center justify-center gap-2 text-center
                                                    ${selectedOutputs.includes(key as OutputOption) 
                                                        ? 'border-[var(--nxt-pink)] bg-[var(--nxt-pink)]/5 text-[var(--text-primary)] shadow-md' 
                                                        : 'border-[var(--border-primary)] bg-[var(--bg-tertiary)] text-[var(--text-tertiary)] hover:border-[var(--text-tertiary)]'
                                                    }`}
                                            >
                                                <span>{METHODOLOGY_INFO[key as OutputOption].title}</span>
                                            </button>
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); setShowMethodology(key as OutputOption); }}
                                                className="absolute top-1 right-1 w-4 h-4 rounded-full bg-gray-200 text-[8px] text-gray-600 flex items-center justify-center hover:bg-gray-300 opacity-0 group-hover:opacity-100 transition-opacity"
                                            >
                                                i
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            <FileUpload onFilesSelected={(newFiles) => setFiles([...files, ...newFiles])} isLoading={false} />

                            {files.length > 0 && (
                                <div className="grid gap-2 mb-2">
                                    {files.map((file, idx) => (
                                        <div key={idx} className="flex items-center justify-between p-3 bg-[var(--bg-tertiary)] rounded-lg border border-[var(--border-secondary)]">
                                            <div className="flex items-center gap-3 overflow-hidden">
                                                <span className="text-xl flex-shrink-0">📄</span>
                                                <div className="overflow-hidden">
                                                    <div className="text-sm font-bold text-[var(--text-primary)] truncate">{file.name}</div>
                                                    <div className="text-[10px] text-[var(--text-tertiary)] uppercase flex gap-2">
                                                        <span>{file.type || 'Unknown Type'}</span>
                                                        <span>•</span>
                                                        <span>{(file.size / 1024).toFixed(0)} KB</span>
                                                    </div>
                                                </div>
                                            </div>
                                            <button 
                                                onClick={() => setFiles(files.filter((_, i) => i !== idx))} 
                                                className="w-6 h-6 flex items-center justify-center rounded-full hover:bg-red-100 text-gray-400 hover:text-red-500 transition-colors"
                                                title="Remove file"
                                            >
                                                ✕
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            )}

                            <button 
                                onClick={startAnalysis}
                                disabled={files.length === 0}
                                className={`w-full py-4 rounded-xl font-bold text-lg text-white shadow-lg transition-all transform active:scale-95
                                    ${files.length > 0 ? 'btn-primary' : 'bg-gray-300 cursor-not-allowed'}
                                `}
                            >
                                Begin Analysis Sequence
                            </button>
                        </div>

                        {/* SAVED PROJECTS */}
                        {savedProjects.length > 0 && (
                            <div className="max-w-3xl mx-auto mt-16 animate-fade-in">
                                <div className="flex items-center gap-3 mb-6">
                                     <div className="h-px bg-[var(--border-primary)] flex-1"></div>
                                     <span className="text-xs font-bold uppercase text-[var(--text-tertiary)] tracking-widest">Recent Investigations</span>
                                     <div className="h-px bg-[var(--border-primary)] flex-1"></div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {savedProjects.map((p) => (
                                        <div 
                                            key={p.id} 
                                            onClick={() => loadProject(p)}
                                            className="group bg-[var(--card-bg)] p-5 rounded-xl border border-[var(--border-primary)] hover:border-[var(--nxt-pink)] cursor-pointer transition-all shadow-sm hover:shadow-md relative overflow-hidden"
                                        >
                                            <div className="absolute top-0 right-0 p-3 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button 
                                                    onClick={(e) => { e.stopPropagation(); deleteProject(p.id); }}
                                                    className="text-xs text-red-400 hover:text-red-600 font-bold"
                                                >
                                                    DELETE
                                                </button>
                                            </div>

                                            <div className="flex justify-between items-start mb-2">
                                                <div className="w-10 h-10 rounded-full bg-gradient-to-br from-[var(--bg-tertiary)] to-[var(--bg-secondary)] border border-[var(--border-primary)] flex items-center justify-center text-lg mb-2">
                                                     {p.selectedOutputs.includes('VIDEO_SCRIPT') ? '🎬' : p.selectedOutputs.includes('STRATEGY_DECK') ? '📊' : '📄'}
                                                </div>
                                                <span className="text-[10px] font-mono text-[var(--text-tertiary)]">{new Date(p.createdAt).toLocaleDateString()}</span>
                                            </div>

                                            <h4 className="font-bold text-sm text-[var(--text-primary)] mb-1 truncate">{p.name || "Untitled Research"}</h4>
                                            <p className="text-xs text-[var(--text-secondary)] line-clamp-2 mb-3 h-8">{p.goal}</p>

                                            <div className="flex flex-wrap gap-1">
                                                {p.selectedOutputs.slice(0, 3).map(o => (
                                                    <span key={o} className="text-[9px] px-1.5 py-0.5 bg-[var(--bg-tertiary)] rounded text-[var(--text-tertiary)] border border-[var(--border-secondary)]">
                                                        {METHODOLOGY_INFO[o]?.title || o}
                                                    </span>
                                                ))}
                                                 {p.selectedOutputs.length > 3 && <span className="text-[9px] px-1.5 py-0.5 text-[var(--text-tertiary)]">+{p.selectedOutputs.length - 3}</span>}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </motion.div>
                )}

                {/* ANALYZING STATE */}
                {appState === AppState.ANALYZING && (
                    <LiveResearchBoard 
                        ingestion={ingestionResult}
                        themes={themesResult}
                        personas={personasResult}
                        journeyMap={journeyResult}
                        prd={prdResult}
                        roadmap={roadmapResult}
                        techArch={techResult}
                        recommendations={recsResult}
                        structure={structureResult}
                        events={thinkingEvents}
                        currentStatus={statusMessage}
                        onEdit={(stage) => setActiveStage(stage)}
                   />
                )}

                {/* RESULTS STATE */}
                {appState === AppState.SUCCESS && result && (
                    <ResultsView result={result} onReset={() => window.location.reload()} onSave={handleSaveProject} onEdit={(stage) => setActiveStage(stage)} />
                )}

            </main>

            {/* MODALS */}
            <AnimatePresence>
                {activeStage !== AnalysisStage.IDLE && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
                        <AnalysisCheckpoint 
                            stage={activeStage}
                            data={
                                activeStage === AnalysisStage.INGESTION ? ingestionResult :
                                activeStage === AnalysisStage.THEMES ? themesResult :
                                activeStage === AnalysisStage.PERSONAS ? personasResult :
                                activeStage === AnalysisStage.JOURNEY_MAP ? journeyResult :
                                activeStage === AnalysisStage.PRD ? prdResult :
                                activeStage === AnalysisStage.ROADMAP ? roadmapResult :
                                activeStage === AnalysisStage.TECH_ARCH ? techResult :
                                activeStage === AnalysisStage.RECOMMENDATIONS ? recsResult :
                                activeStage === AnalysisStage.DECK_STRUCTURE ? structureResult :
                                activeStage === AnalysisStage.NARRATIVE ? narrativeResult : null
                            }
                            isProcessing={statusMessage.includes('...')}
                            onApprove={handleCheckpointApproval}
                            onClose={() => setActiveStage(AnalysisStage.IDLE)}
                            currentLog={thinkingEvents[thinkingEvents.length - 1]?.content}
                        />
                    </div>
                )}

                {showMethodology && (
                    <MethodologyModal outputId={showMethodology} onClose={() => setShowMethodology(null)} />
                )}
            </AnimatePresence>

        </div>
    );
};

export default App;

