                                            className="w-full bg-white text-lg italic font-serif p-3 rounded-lg h-28 resize-none border-l-4 border-[var(--nxt-pink)] shadow-sm focus:border-indigo-500 outline-none"
                                         />
                                      </div>
                                  </div>
                              </div>
                          ))}
                      </div>
                  )}

              </div>
          </div>

          <EvidenceModal 
              isOpen={modalOpen} 
              onClose={() => setModalOpen(false)} 
              title={modalData.title} 
              content={modalData.content} 
              citations={modalData.citations}
              quote={modalData.quote}
          />
      </div>
  );
};

