                                          <div className="md:col-span-2 p-6 flex flex-col gap-6">
                                              <div>
                                                  <div className="flex justify-between items-start mb-2">
                                                      <input 
                                                          value={p.name}
                                                          onChange={e => updatePersonaField(i, 'name', e.target.value)}
                                                          className="text-3xl font-bold bg-transparent outline-none focus:border-b border-indigo-500 w-full"
                                                      />
                                                  </div>
                                                  <input 
                                                      value={p.role}
                                                      onChange={e => updatePersonaField(i, 'role', e.target.value)}
                                                      className="text-indigo-600 font-bold bg-transparent outline-none focus:border-b border-indigo-500 w-full mb-1"
                                                  />
                                                  <input 
                                                      value={p.demographics}
                                                      onChange={e => updatePersonaField(i, 'demographics', e.target.value)}
