};

// --- RETRY LOGIC ---
const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function withRetry<T>(
    operation: () => Promise<T>, 
    retries = 3, 
    baseDelay = 2000, 
    operationName = "Gemini API Call"
): Promise<T> {
    let lastError: any;

    for (let i = 0; i < retries; i++) {
        try {
            return await operation();
        } catch (error: any) {
            lastError = error;
            const isTransient = 
                error.status === 503 || 
                error.code === 503 || 
                error.message?.includes('503') || 
                error.message?.includes('overloaded') ||
                error.status === 429 ||
                error.code === 429;

            if (isTransient && i < retries - 1) {
                const delay = baseDelay * Math.pow(2, i);
                console.warn(`${operationName} failed with ${error.status || 'error'}. Retrying in ${delay}ms... (Attempt ${i + 1}/${retries})`);
                await wait(delay);
                continue;
            }
            break;
        }
    }
    throw lastError;
}

// --- IMAGE GENERATION HELPERS ---

export const generateImage = async (prompt: string, aspectRatio: string = "16:9", refImageBase64?: string): Promise<string | undefined> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let styleDirectives = "";
    let negativeConstraints = "";

    // Specific Prompt Strategy based on Aspect Ratio context
    if (aspectRatio === "1:1" || aspectRatio === "3:4") {
        // PERSONA / PORTRAIT / SPLIT SLIDE MODE
        styleDirectives = "Style: Modern, professional illustration in the style of Laci Jordan. Bold vibrant colors, flat design, clean lines, professional character representation. Context: Authentic professional user behavior.";
        negativeConstraints = "Do not include: photorealism, 3D render, cartoonish exaggeration, anime, surrealism, floating objects, abstract nonsense, messy scribbles, confusing metaphors.";
    } else {
        // SCENE / SLIDE MODE (16:9) - UPDATED STYLE
        styleDirectives = "Style: Modern, professional corporate illustration in the style of Laci Jordan. Bold vibrant colors, flat design, clean lines. Context: Business research insights. Visuals should be literal and straightforward representations of the content, not surreal metaphors.";
        negativeConstraints = "Do not include: photorealism, 3D render, dark mode, gritty texture, messy scribbles, illegible text, complex shading, clutter, cinematic lighting, surrealism, weird abstraction, confusing elements.";
    }

    // Force strict adherence to the subject matter
    const finalPrompt = `Depict specifically: ${prompt}. Ensure all visual elements are extremely related to this description. ${styleDirectives} ${negativeConstraints}`; 

    const parts: any[] = [{ text: finalPrompt }];
    if (refImageBase64) {
        const cleanBase64 = refImageBase64.includes('base64,') 
            ? refImageBase64.split('base64,')[1] 
            : refImageBase64;

        parts.unshift({
            inlineData: {
                mimeType: 'image/png',
                data: cleanBase64
            }
        });
        parts[parts.length-1].text += " Maintain strict character consistency with the reference image.";
    }

    const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: parts
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio as any,
          imageSize: "1K"
        }
      }
    }), 3, 2000, "Image Generation");

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        const mimeType = part.inlineData.mimeType || 'image/jpeg';
        return `data:${mimeType};base64,${part.inlineData.data}`;
      }
    }
  } catch (error) {
    console.warn("Image generation failed for prompt:", prompt, error);
    return undefined;
  }
  return undefined;
};

// --- VIDEO GENERATION (VEO 3) ---
export const generateSceneVideo = async (prompt: string, imageBase64?: string): Promise<string | undefined> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        let operation;

        // Clean base64 if provided
        const cleanBase64 = imageBase64?.includes('base64,') ? imageBase64.split('base64,')[1] : imageBase64;

        // Updated Video Prompt for Infographic Style
        const styleSuffix = ". Modern, professional corporate illustration animation in the style of Laci Jordan. Flat 2D motion. Bold colors. Clean and straightforward. No surrealism.";
        const fullPrompt = `Animate strictly based on this description: ${prompt}. Ensure visual relevance. ${styleSuffix}`;

        if (cleanBase64) {
             operation = await ai.models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: fullPrompt,
                image: {
                    imageBytes: cleanBase64,
                    mimeType: 'image/png', 
                },
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
            });
        } else {
             operation = await ai.models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: fullPrompt,
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
            });
        }

        // Poll for completion
        let retries = 0;
        while (!operation.done && retries < 30) { // Timeout after ~2.5 mins
            await new Promise(resolve => setTimeout(resolve, 5000)); // Poll every 5s
            operation = await ai.operations.getVideosOperation({operation: operation});
            retries++;
        }

        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (downloadLink) {
             // Fetch the bytes using API Key
             const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
             const blob = await response.blob();
             return URL.createObjectURL(blob);
        }
    } catch (e) {
        console.error("Veo generation failed", e);
    }
    return undefined;
};

