            ? `USER INTERVENTION: "${feedback}". \nCRITICAL INSTRUCTION: You MUST regenerate the 'personas' array to reflect this feedback.`
            : "Themes approved.";

        const prompt = `
            ${feedbackPrompt}
            ${themesContext}
            STEP 3: PERSONA SYNTHESIS.
            Identify distinct user personas based on the ACTIVE themes.
            Apply the 5 W's framework.

            Output JSON matching schema.
        `;

        const citationSchema: Schema = {
            type: Type.OBJECT,
            properties: {
                sourceFile: { type: Type.STRING },
                text: { type: Type.STRING },
