      if (activeTab === 'personas') {
          data = personasData.map(p => ({
              Name: p.name, Role: p.role, Quote: p.quote, Bio: p.bio, 
              PainPoints: p.painPoints.map(pp => pp.label).join('; ')
          }));
          filename = 'personas.csv';
      } else if (activeTab === 'prd' && prdData) {
          data = prdData.features.map(f => ({
              Feature: f.name, Priority: f.priority, Description: f.description, UserStories: f.userStories.join('; ')
          }));
          filename = 'prd_features.csv';
      } else if (activeTab === 'roadmap' && roadmapData) {
          data = roadmapData.items.map(i => ({
              Initiative: i.initiative, Horizon: i.horizon, Status: i.status, Owner: i.owner, Description: i.description
          }));
          filename = 'roadmap.csv';
      } else if (activeTab === 'journey' && journeyData) {
          data = journeyData;
          filename = 'service_blueprint.csv';
      } else if (activeTab === 'tech' && techData) {
          data = techData.nodes.map(n => ({
              Label: n.label, Type: n.type, Description: n.description
          }));
          filename = 'tech_nodes.csv';
      } else if (activeTab === 'strategy' && result.recommendations) {
          data = result.recommendations.map(r => ({
              Title: r.title, Impact: r.impactLevel, Description: r.description, ActionItems: r.actionItems.join('; ')
          }));
          filename = 'strategic_recs.csv';
      } else if (activeTab === 'deck' && slides.length > 0) {
          data = slides.map(s => ({
              Slide: s.slideNumber, Title: s.title, Layout: s.layout, Content: (s.content || []).join('; '), VisualPrompt: s.visualPrompt
          }));
          filename = 'strategy_deck.csv';
      } else if (activeTab === 'script' && scriptScenes.length > 0) {
          data = scriptScenes.map(s => ({
              Scene: s.sceneNumber, Narration: s.audioNarration, Visual: s.visualDescription
          }));
          filename = 'video_script.csv';
      }

      if (data.length > 0) {
          const csv = convertToCSV(data);
          downloadCSV(csv, filename);
      } else {
          alert("No structured data available for CSV export on this tab.");
      }
  };

  const handleDownloadPDF = async () => {
      if (!contentRef.current) return;
      setIsExporting(true);
      try {
          if (activeTab === 'deck') {
              // Strategy Deck: Enforce 1 slide per page in STRICT 16:9 Landscape based on CAPTURE dimensions
              const slideElements = contentRef.current.querySelectorAll('.slide-export-target');

              if (slideElements.length === 0) {
                  alert("No slides found to export.");
                  setIsExporting(false);
                  return;
              }

              // Initialize PDF. We will set page size dynamically for each slide to ensure no squashing.
              // Standard A4 Landscape Width is 297mm.
              const pdf = new jsPDF({
                  orientation: 'landscape',
                  unit: 'mm',
                  format: 'a4' 
              });

              // Remove the initial page as we will add pages with specific dimensions
              pdf.deletePage(1);

              for (let i = 0; i < slideElements.length; i++) {
                  const slideElement = slideElements[i] as HTMLElement;

                  const canvas = await html2canvas(slideElement, { 
                      scale: 2, // High resolution
                      useCORS: true, 
                      logging: false, 
                      backgroundColor: '#ffffff' 
                  });

                  // Calculate dimensions to maintain aspect ratio perfectly
                  const imgWidth = canvas.width;
                  const imgHeight = canvas.height;
                  const ratio = imgWidth / imgHeight;

                  // PDF Page Width (A4 Landscape Width)
                  const pdfPageWidth = 297; 
                  // Calculate Height based on the actual captured ratio to avoid squashing
                  const pdfPageHeight = pdfPageWidth / ratio;

                  pdf.addPage([pdfPageWidth, pdfPageHeight], 'landscape');
                  pdf.addImage(canvas, 'PNG', 0, 0, pdfPageWidth, pdfPageHeight);
              }
              const filename = activeTab === 'deck' ? 'NXT_Humans_Strategy_Deck.pdf' : 'NXT_Humans_Personas.pdf';
              pdf.save(filename);
          } 
          else if (activeTab === 'personas') {
              // PERSONAS EXPORT LOGIC: Fixed 16:9 Slide, Centered Content (No Stretching)
              const slideElements = contentRef.current.querySelectorAll('.persona-card');

              if (slideElements.length === 0) {
                  alert("No personas found to export.");
                  setIsExporting(false);
                  return;
              }

              // Define strict 16:9 Slide Dimensions (Standard Landscape Presentation)
              const pageWidth = 297; // mm
              const pageHeight = 167.06; // mm (297 / (16/9))

              const pdf = new jsPDF({
                  orientation: 'landscape',
                  unit: 'mm',
                  format: [pageWidth, pageHeight] // Custom 16:9 format
              });

              pdf.deletePage(1);

              for (let i = 0; i < slideElements.length; i++) {
                  const slideElement = slideElements[i] as HTMLElement;

                  // Capture the persona card
                  const canvas = await html2canvas(slideElement, { 
                      scale: 2, 
                      useCORS: true, 
                      logging: false, 
                      backgroundColor: '#ffffff' 
                  });

                  // Dimensions of the captured image
                  const imgWidthRaw = canvas.width;
                  const imgHeightRaw = canvas.height;
                  const imgRatio = imgWidthRaw / imgHeightRaw;

                  // Dimensions of the target PDF Page
                  const pageRatio = pageWidth / pageHeight;

                  let finalW, finalH;

                  // "Contain" Logic: Fit image within page bounds without stretching
                  if (imgRatio > pageRatio) {
                      // Image is wider than the page relative to height
                      finalW = pageWidth;
                      finalH = pageWidth / imgRatio;
                  } else {
                      // Image is taller than the page relative to width
                      finalH = pageHeight;
                      finalW = pageHeight * imgRatio;
                  }

                  // Center the image
                  const x = (pageWidth - finalW) / 2;
                  const y = (pageHeight - finalH) / 2;

                  pdf.addPage([pageWidth, pageHeight], 'landscape');
                  // Add image centered
                  pdf.addImage(canvas, 'PNG', x, y, finalW, finalH);
              }
              pdf.save('NXT_Humans_Personas.pdf');
          }
          else if (activeTab === 'journey' || activeTab === 'tech') {
              // Special Split Export: Diagram on one slide, Details on subsequent slides
              const pdf = new jsPDF('landscape', 'mm', 'a4');
              pdf.deletePage(1); // Reset

              // 1. Capture Diagram (if exists)
              const diagramEl = contentRef.current.querySelector('.diagram-container') as HTMLElement;
              if (diagramEl) {
                  const canvas = await html2canvas(diagramEl, { scale: 2, useCORS: true, logging: false, backgroundColor: '#ffffff' });
                  const imgWidth = canvas.width;
                  const imgHeight = canvas.height;
                  const ratio = imgWidth / imgHeight;
                  const pdfPageWidth = 297;
                  const pdfPageHeight = pdfPageWidth / ratio;

                  pdf.addPage([pdfPageWidth, pdfPageHeight], 'landscape');
                  pdf.addImage(canvas, 'PNG', 0, 0, pdfPageWidth, pdfPageHeight);
              }

              // 2. Capture Details
              const detailsEl = contentRef.current.querySelector('.details-container') as HTMLElement;
              if (detailsEl) {
                  const canvas = await html2canvas(detailsEl, { scale: 2, useCORS: true, logging: false, backgroundColor: '#ffffff' });

                  // For scrolling content, we use standard A4 Landscape pages
                  const pdfPageWidth = 297; 
                  const pdfPageHeight = 210; // A4 Landscape Height

                  const imgData = canvas.toDataURL('image/png');
                  const imgPropsWidth = pdfPageWidth;
                  const imgPropsHeight = (canvas.height * imgPropsWidth) / canvas.width;

                  let heightLeft = imgPropsHeight;
                  let position = 0;

                  pdf.addPage('a4', 'landscape');
                  pdf.addImage(imgData, 'PNG', 0, position, imgPropsWidth, imgPropsHeight);
                  heightLeft -= pdfPageHeight;

                  while (heightLeft > 0) {
                      position = heightLeft - imgPropsHeight; // Move up
                      pdf.addPage('a4', 'landscape');
                      pdf.addImage(imgData, 'PNG', 0, position, imgPropsWidth, imgPropsHeight); // This logic paints the remaining part
                      heightLeft -= pdfPageHeight;
                  }
              }

              pdf.save(`Humans_in_Control_${activeTab}_Export.pdf`);
          }
          else {
              // Standard scrolling export for other tabs (e.g. Roadmap, PRD)
              const orientation = (activeTab === 'roadmap') ? 'l' : 'p';
              const pdf = new jsPDF(orientation, 'mm', 'a4');
              const pdfWidth = pdf.internal.pageSize.getWidth();
              const pdfHeight = pdf.internal.pageSize.getHeight();

              const canvas = await html2canvas(contentRef.current, { scale: 2, useCORS: true, logging: false, backgroundColor: '#ffffff' });

              const imgData = canvas.toDataURL('image/png');
              const imgWidth = pdfWidth;
              const imgHeight = (canvas.height * imgWidth) / canvas.width;

              let heightLeft = imgHeight;
              let position = 0;
              pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
              heightLeft -= pdfHeight;
              while (heightLeft > 0) {
                  position = heightLeft - imgHeight;
                  pdf.addPage();
                  pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
                  heightLeft -= pdfHeight;
              }
              pdf.save(`Humans_in_Control_Export_${activeTab}.pdf`);
          }
      } catch (e) {
          console.error("PDF Export failed", e);
          alert("Export failed. Please try again.");
      } finally {
          setIsExporting(false);
      }
  };

  const handleGenerateVideo = async (index: number) => {
    const scene = scriptScenes[index];
    if (scene.videoStatus === 'generating' || scene.videoStatus === 'completed') return;

    const newScenes = [...scriptScenes];
    newScenes[index] = { ...scene, videoStatus: 'generating' };
    setScriptScenes(newScenes);

    try {
        const videoUrl = await generateSceneVideo(scene.visualDescription, scene.imageUrl);
        setScriptScenes(prev => {
            const updated = [...prev];
            if (videoUrl) {
                updated[index] = { ...updated[index], videoUrl: videoUrl, videoStatus: 'completed' };
            } else {
                 updated[index] = { ...updated[index], videoStatus: 'error' };
            }
            return updated;
        });
    } catch (e) {
        setScriptScenes(prev => {
            const updated = [...prev];
            updated[index] = { ...updated[index], videoStatus: 'error' };
            return updated;
        });
    }
  };

  const handleRegeneratePersonaImage = async (index: number) => {
      const p = personasData[index];
      const newPersonas = [...personasData];
      newPersonas[index] = { ...p, imageUrl: undefined }; 
      setPersonasData(newPersonas);

      try {
          const bioSnippet = p.bio ? p.bio.substring(0, 50) : "";
          const imgPrompt = `Photorealistic portrait of ${p.name}, ${p.role}, ${p.demographics}. Context: ${bioSnippet}. In an environment reflecting their daily behavior. Racially diverse, authentic, candid photography, 85mm lens, cinematic lighting. High resolution. No futuristic elements, no illustrations, no 3D render.`;
          const url = await generateImage(imgPrompt, "1:1");

          setPersonasData(prev => {
              const updated = [...prev];
              updated[index] = { ...updated[index], imageUrl: url };
              return updated;
          });
      } catch(e) {
          console.error("Persona regen failed", e);
      }
  };

  const handleRegenerateDiagram = async (type: 'journey' | 'tech') => {
       // Set specific loading state
       setDiagramStatus(prev => ({...prev, [type]: 'generating'}));
       try {
           if (type === 'journey' && journeyData.length > 0) {
                // Keep the old URL momentarily if desired, or clear it. 
                // We will clear it to show loading state clearly.
                setJourneyDiagramUrl(undefined); 

                const stagesStr = journeyData.map(s => `${s.phase}: ${s.customerAction}`).join("; ");
                const imgPrompt = `A gorgeous, professional Service Blueprint visualization. Flat vector design. White background. Clean modern lines. Phases: ${stagesStr}. Infographic style. No photorealism. High fidelity.`;
                const url = await generateImage(imgPrompt, "16:9");
                setJourneyDiagramUrl(url);
           }
           if (type === 'tech' && techData) {
               setTechDiagramUrl(undefined);

                const nodesList = techData.nodes.map(n => n.label).join(", ");
                const imgPrompt = `A gorgeous, professional system flow diagram visualization. White background. Clean vector lines. Nodes: ${nodesList}. Technical architecture style. No photorealism. Infographic style.`;
                const url = await generateImage(imgPrompt, "16:9");
                setTechDiagramUrl(url);
           }
       } catch (e) {
           console.error("Diagram regen failed", e);
       } finally {
           setDiagramStatus(prev => ({...prev, [type]: 'idle'}));
       }
  };

  const handleRegenerateImage = async (index: number) => {
    const scene = scriptScenes[index];
    if (scene.imageStatus === 'generating') return;

    const newScenes = [...scriptScenes];
    newScenes[index] = { ...scene, imageStatus: 'generating' };
    setScriptScenes(newScenes);

    try {
        let refImage = undefined;
        if (scene.personaRef) {
             const persona = result.personas.find(p => p.name === scene.personaRef);
             if (persona?.imageUrl) refImage = persona.imageUrl;
        }
        const imageUrl = await generateImage(scene.visualPrompt || scene.visualDescription, "16:9", refImage);
        setScriptScenes(prev => {
            const updated = [...prev];
            updated[index] = { ...updated[index], imageUrl: imageUrl, imageStatus: 'idle', videoUrl: undefined, videoStatus: 'idle' };
            return updated;
        });
    } catch (e) {
        setScriptScenes(prev => {
            const updated = [...prev];
            updated[index] = { ...updated[index], imageStatus: 'error' };
            return updated;
        });
    }
  };

  const handleRegenerateSlideImage = async (index: number) => {
    const slide = slides[index];
    if (slide.imageStatus === 'generating') return;

    const newSlides = [...slides];
    newSlides[index] = { ...slide, imageStatus: 'generating' };
    setSlides(newSlides);

    try {
        let aspectRatio = "16:9";
        if (slide.layout === 'CONTENT_SPLIT_RIGHT' || slide.layout === 'CONTENT_SPLIT_LEFT') {
            aspectRatio = "1:1";
        }
        const imageUrl = await generateImage(slide.visualPrompt, aspectRatio);
        setSlides(prev => {
            const updated = [...prev];
            updated[index] = { ...updated[index], imageUrl: imageUrl, imageStatus: 'idle' };
            return updated;
        });
    } catch (e) {
        setSlides(prev => {
            const updated = [...prev];
            updated[index] = { ...updated[index], imageStatus: 'error' };
            return updated;
        });
    }
  };

  // Slide Editing Handlers
  const startEditingSlide = (index: number) => {
      setEditingSlideIndex(index);
      setEditForm({ ...slides[index] });
      setRewriteThemeId('');
  };

  const saveSlideEdit = () => {
      if (editingSlideIndex === null || !editForm) return;
      const newSlides = [...slides];
      newSlides[editingSlideIndex] = editForm;
      setSlides(newSlides);
      setEditingSlideIndex(null);
      setEditForm(null);
  };

  const cancelSlideEdit = () => {
      setEditingSlideIndex(null);
      setEditForm(null);
  };

  const handleRewriteSlide = async () => {
      if (!rewriteThemeId || !editForm || editingSlideIndex === null) return;
      const theme = result.themes[parseInt(rewriteThemeId)];
      if (!theme) return;

      setIsRewriting(true);
      try {
          const rewrittenData = await rewriteSlideContent(editForm, theme, editForm.layout);
          setEditForm(prev => prev ? ({ ...prev, ...rewrittenData, style: prev.style }) : null);
      } catch (e) {
          console.error("Rewrite error", e);
      } finally {
          setIsRewriting(false);
      }
  };

  const renderSlidePreview = (slide: Slide, idx: number) => {
      // Enforce 16:9 Aspect Ratio Container for Nano Banana Pro compliance
      const containerClass = "slide-export-target rounded-none shadow-xl max-w-5xl mx-auto aspect-[16/9] flex flex-col relative overflow-hidden group border border-[var(--border-secondary)] transition-all hover:scale-[1.01]";
      const { style } = slide;

      if (editingSlideIndex === idx && editForm) {
          return (
              <div key={idx} className="max-w-5xl mx-auto bg-[var(--card-bg)] rounded-xl p-6 border border-[var(--border-primary)] shadow-2xl animate-fade-in relative z-10 text-[var(--text-primary)]">
                  <div className="flex justify-between items-center mb-6 pb-4 border-b border-[var(--border-primary)]">
                      <h3 className="text-xl font-bold">Edit Slide {slide.slideNumber}</h3>
                      <div className="flex gap-2">
                           <button onClick={cancelSlideEdit} className="px-3 py-1 text-sm text-[var(--text-tertiary)] hover:text-[var(--text-primary)] transition-colors">Cancel</button>
                           <button onClick={saveSlideEdit} className="px-4 py-1 text-sm bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded shadow-lg shadow-indigo-600/20">Save Changes</button>
                      </div>
                  </div>

                  <div className="grid md:grid-cols-2 gap-8">
                      <div className="space-y-4">
                          <div>
                              <label className="text-xs font-bold text-[var(--text-tertiary)] uppercase block mb-1">Layout Template</label>
                              <select 
                                value={editForm.layout}
                                onChange={e => setEditForm({...editForm, layout: e.target.value as SlideLayout})}
                                className="w-full bg-white text-black border border-[var(--border-primary)] rounded p-2 text-sm focus:border-indigo-500 outline-none"
                                style={{ color: 'black', backgroundColor: 'white' }}
                              >
                                  <option value="TITLE_SLIDE">Title Slide</option>
                                  <option value="SECTION_HEADER">Section Header</option>
                                  <option value="CONTENT_SPLIT_RIGHT">Standard (Text Left / Image Right)</option>
                                  <option value="CONTENT_SPLIT_LEFT">Standard (Image Left / Text Right)</option>
                                  <option value="FULL_BLEED_IMAGE">Full Bleed Image (Overlay Text)</option>
                                  <option value="TYPOGRAPHY_QUOTE">Typography Quote</option>
                              </select>
                          </div>
                          <div>
                              <label className="text-xs font-bold text-[var(--text-tertiary)] uppercase block mb-1">Slide Title</label>
                              <input 
                                  type="text"
                                  value={editForm.title}
                                  onChange={e => setEditForm({...editForm, title: e.target.value})}
                                  className="w-full bg-[var(--input-bg)] border border-[var(--border-primary)] rounded p-2 text-sm text-[var(--text-primary)] focus:border-indigo-500 outline-none font-bold"
                              />
                          </div>
                          <div>
                              <label className="text-xs font-bold text-[var(--text-tertiary)] uppercase block mb-1">Main Content (Bullet Points)</label>
                              <textarea 
                                  value={(editForm.content || []).join('\n')}
                                  onChange={e => setEditForm({...editForm, content: e.target.value.split('\n')})}
                                  className="w-full h-32 bg-[var(--input-bg)] border border-[var(--border-primary)] rounded p-2 text-sm text-[var(--text-secondary)] focus:border-indigo-500 outline-none resize-none leading-relaxed"
                                  placeholder="One bullet per line..."
                              />
                          </div>
                      </div>
                      <div className="space-y-4">
                          <div>
                              <label className="text-xs font-bold text-[var(--text-tertiary)] uppercase block mb-1">Visual Prompt (Gemini 3 Pro)</label>
                              <textarea 
                                  value={editForm.visualPrompt}
                                  onChange={e => setEditForm({...editForm, visualPrompt: e.target.value})}
                                  className="w-full h-24 bg-[var(--input-bg)] border border-[var(--border-primary)] rounded p-2 text-xs text-[var(--text-secondary)] focus:border-indigo-500 outline-none resize-none font-mono"
                              />
                          </div>
                          <div>
                              <label className="text-xs font-bold text-[var(--text-tertiary)] uppercase block mb-1">Voiceover / Narrative</label>
                              <textarea 
                                  value={editForm.narrative}
                                  onChange={e => setEditForm({...editForm, narrative: e.target.value})}
                                  className="w-full h-24 bg-[var(--input-bg)] border border-[var(--border-primary)] rounded p-2 text-sm text-[var(--text-secondary)] focus:border-indigo-500 outline-none resize-none italic"
                              />
                          </div>
                          <div className="bg-indigo-50 border border-indigo-100 rounded-lg p-3">
                              <label className="text-xs font-bold text-indigo-800 uppercase block mb-2">✨ AI Rewrite Tool</label>
                              <div className="flex gap-2">
                                  <select 
                                      value={rewriteThemeId}
                                      onChange={e => setRewriteThemeId(e.target.value)}
                                      className="flex-1 text-xs p-2 rounded border border-indigo-200 text-indigo-900 bg-white outline-none"
                                      style={{ color: 'black', backgroundColor: 'white' }}
                                  >
                                      <option value="">Select a Theme to Pivot this slide towards...</option>
                                      {result.themes.map((t, i) => (
                                          <option key={i} value={i}>{t.name}</option>
                                      ))}
                                  </select>
                                  <button 
                                      onClick={handleRewriteSlide}
                                      disabled={!rewriteThemeId || isRewriting}
                                      className="bg-indigo-600 text-white text-xs px-3 py-2 rounded font-bold hover:bg-indigo-700 disabled:opacity-50"
                                  >
                                      {isRewriting ? '...' : 'Rewrite'}
                                  </button>
                              </div>
                          </div>
                      </div>
                  </div>
              </div>
          );
      }

      return (
          <div key={idx} className={containerClass} style={{ backgroundColor: style.backgroundColor }}>
               {/* Content Layouts */}
               {slide.layout === 'TITLE_SLIDE' && (
                   <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-10">
                       <h3 className="text-xl tracking-[0.3em] font-bold mb-4 opacity-80" style={{ color: style.headerColor }}>STRATEGIC ANALYSIS</h3>
                       <h1 className="text-6xl font-black mb-6 tracking-tighter" style={{ color: style.headerColor }}>
                           {slide.title || 'NXT HUMANS'}<span style={{ color: style.accentColor }}>.</span>
                       </h1>
                       <p className="text-xl max-w-2xl leading-relaxed" style={{ color: style.textColor }}>{slide.narrative}</p>
                   </div>
               )}
               {slide.layout === 'SECTION_HEADER' && (
                   <div className="absolute inset-0 flex flex-col items-center justify-center relative">
                       {slide.imageUrl && (
                           <div className="absolute inset-0 z-0">
                               <img src={slide.imageUrl} className="w-full h-full object-cover opacity-40" alt="background" />
                               <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent"></div>
                           </div>
                       )}
                       <div className="relative z-10 text-center p-12">
                           <h2 className="text-5xl font-bold mb-4 tracking-tight" style={{ color: style.headerColor }}>{slide.title}</h2>
                           <p className="text-xl italic font-light opacity-90 max-w-3xl" style={{ color: style.textColor }}>{slide.narrative}</p>
                       </div>
                   </div>
               )}
               {slide.layout === 'FULL_BLEED_IMAGE' && (
                   <div className="absolute inset-0">
                       {slide.imageUrl ? (
                           <img src={slide.imageUrl} className="w-full h-full object-cover" alt="slide visual" />
                       ) : (
                           <div className="w-full h-full bg-gray-800 flex items-center justify-center text-gray-500">No Image Generated</div>
                       )}
                       <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-black/90 to-transparent backdrop-blur-[2px]">
                           <h2 className="text-4xl font-bold mb-2" style={{ color: style.headerColor }}>{slide.title}</h2>
                           <p className="text-lg opacity-90" style={{ color: style.textColor }}>{(slide.content || []).join(' ')}</p>
                       </div>
                   </div>
               )}
               {(slide.layout === 'CONTENT_SPLIT_RIGHT' || slide.layout === 'CONTENT_SPLIT_LEFT') && (
                   <div className={`absolute inset-0 flex ${slide.layout === 'CONTENT_SPLIT_LEFT' ? 'flex-row-reverse' : 'flex-row'}`}>
                       <div className="w-1/2 p-8 flex flex-col justify-center">
                           <h2 className="text-4xl font-bold mb-6" style={{ color: style.headerColor }}>
                               {slide.title}<span style={{ color: style.accentColor }}>.</span>
                           </h2>
                           <div className="space-y-5 mb-8">
                               {(slide.content || []).map((point, i) => (
                                   <div key={i} className="flex gap-3">
                                       <span style={{ color: style.accentColor }}>•</span>
                                       <p className="text-xl leading-snug" style={{ color: style.textColor }}>{point}</p>
                                   </div>
                               ))}
                           </div>
                           <div className="mt-auto pt-6 border-t border-white/10">
                               <p className="text-sm italic opacity-60" style={{ color: style.textColor }}>{slide.narrative}</p>
                           </div>
                       </div>
                       <div className="w-1/2 relative bg-black/20 overflow-hidden flex items-center justify-center">
                           {slide.imageUrl ? (
                               <img src={slide.imageUrl} className="w-full h-full object-cover relative z-10" alt="visual" />
                           ) : (
                               <div className="w-full h-full flex items-center justify-center text-gray-500">Generating Visual...</div>
                           )}
                       </div>
                   </div>
               )}
               {slide.layout === 'TYPOGRAPHY_QUOTE' && (
                    <div className="absolute inset-0 flex flex-col justify-center p-16 relative overflow-hidden">
                        <div className="absolute top-0 right-0 text-[120px] font-serif opacity-10 leading-none select-none" style={{ color: style.accentColor }}>"</div>
                        <h4 className="text-sm font-bold tracking-[0.2em] mb-8 uppercase opacity-60" style={{ color: style.accentColor }}>Key Insight</h4>
                        <p className="text-3xl font-serif italic leading-tight mb-8 relative z-10" style={{ color: style.textColor }}>
                            "{slide.quote}"
                        </p>
                        <p className="text-sm opacity-50" style={{ color: style.textColor }}>— Research Evidence</p>
                    </div>
               )}

               <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity flex gap-2 z-20">
                   <button onClick={() => deleteSlide(idx)} className="bg-red-500 text-white px-3 py-1 rounded-full text-xs font-bold shadow-lg hover:bg-red-600 mr-2">Delete</button>
                   <button onClick={() => startEditingSlide(idx)} className="bg-white text-black px-3 py-1 rounded-full text-xs font-bold shadow-lg hover:bg-gray-100">Edit Slide</button>
                   <button onClick={() => handleRegenerateSlideImage(idx)} className="bg-black/50 text-white backdrop-blur px-3 py-1 rounded-full text-xs hover:bg-black/70 flex items-center gap-1">
                       {slide.imageStatus === 'generating' ? '⟳ ...' : '⟳ Regen Image'}
                   </button>
               </div>

               <div className="absolute top-4 left-4 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col gap-1 z-20">
                   <button onClick={() => moveSlide(idx, 'up')} disabled={idx === 0} className="w-6 h-6 flex items-center justify-center bg-black/50 text-white rounded-full disabled:opacity-30 hover:bg-black/80">▲</button>
                   <button onClick={() => moveSlide(idx, 'down')} disabled={idx === slides.length-1} className="w-6 h-6 flex items-center justify-center bg-black/50 text-white rounded-full disabled:opacity-30 hover:bg-black/80">▼</button>
               </div>

               <div className="absolute bottom-4 right-6 text-xs font-mono opacity-30 mix-blend-difference" style={{ color: 'white' }}>
                   {idx + 1} / {slides.length}
               </div>
          </div>
      );
  };

  const isOutputSelected = (opt: OutputOption) => result.selectedOutputs?.includes(opt);

  const handleEditClick = () => {
    if (!onEdit) return;

    switch (activeTab) {
        case 'personas':
            onEdit(AnalysisStage.PERSONAS);
            break;
        case 'deck':
        case 'script':
            onEdit(AnalysisStage.NARRATIVE);
            break;
        case 'strategy':
            onEdit(AnalysisStage.RECOMMENDATIONS);
            break;
        case 'prd':
            onEdit(AnalysisStage.PRD);
            break;
        case 'roadmap':
            onEdit(AnalysisStage.ROADMAP);
            break;
        case 'journey':
            onEdit(AnalysisStage.JOURNEY_MAP);
            break;
        case 'tech':
            onEdit(AnalysisStage.TECH_ARCH);
            break;
    }
  };

  return (
      <div className="bg-[var(--bg-secondary)] min-h-screen relative flex flex-col">

          <div className="bg-[var(--bg-primary)] border-b border-[var(--border-primary)] sticky top-0 z-30 px-8 py-4 flex justify-between items-center shadow-sm">
              <div className="flex-1 flex justify-center">
                  <div className="flex bg-[var(--bg-secondary)] rounded-xl p-1.5 border border-[var(--border-primary)] overflow-x-auto gap-1">
                      {isOutputSelected('PERSONAS') && (result.personas && result.personas.length > 0) && (
                          <button onClick={() => setActiveTab('personas')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'personas' ? 'bg-[var(--card-bg)] shadow text-[var(--text-primary)] border border-[var(--border-secondary)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]'}`}>Personas</button>
                      )}
                      {isOutputSelected('STRATEGY_DECK') && (
                          <button onClick={() => setActiveTab('deck')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'deck' ? 'bg-[var(--card-bg)] shadow text-[var(--text-primary)] border border-[var(--border-secondary)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]'}`}>Strategy Deck</button>
                      )}
                      {isOutputSelected('VIDEO_SCRIPT') && (
                          <button onClick={() => setActiveTab('script')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'script' ? 'bg-[var(--card-bg)] shadow text-[var(--text-primary)] border border-[var(--border-secondary)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]'}`}>Video Script</button>
                      )}
                      {isOutputSelected('STRATEGIC_RECS') && (
                          <button onClick={() => setActiveTab('strategy')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'strategy' ? 'bg-[var(--card-bg)] shadow text-[var(--text-primary)] border border-[var(--border-secondary)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]'}`}>Recs</button>
                      )}
                      {isOutputSelected('PRD') && <button onClick={() => setActiveTab('prd')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'prd' ? 'bg-[var(--card-bg)] shadow text-[var(--text-primary)] border border-[var(--border-secondary)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]'}`}>PRD</button>}
                      {isOutputSelected('ROADMAP') && <button onClick={() => setActiveTab('roadmap')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'roadmap' ? 'bg-[var(--card-bg)] shadow text-[var(--text-primary)] border border-[var(--border-secondary)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]'}`}>Roadmap</button>}
                      {isOutputSelected('JOURNEY_MAP') && <button onClick={() => setActiveTab('journey')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'journey' ? 'bg-[var(--card-bg)] shadow text-[var(--text-primary)] border border-[var(--border-secondary)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]'}`}>Blueprint</button>}
                      {isOutputSelected('TECH_ARCH') && <button onClick={() => setActiveTab('tech')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'tech' ? 'bg-[var(--card-bg)] shadow text-[var(--text-primary)] border border-[var(--border-secondary)]' : 'text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]'}`}>Tech Arch</button>}
                  </div>
              </div>
              <div className="flex gap-2">
                   <button onClick={handleExportCSV} className="bg-white hover:bg-gray-50 text-[var(--text-primary)] border border-[var(--border-primary)] px-3 py-2 rounded text-xs font-bold shadow transition-all flex items-center gap-1">📊 Export CSV</button>
                   {activeTab === 'deck' && (
                       <button onClick={handleDownloadPDF} className="bg-white hover:bg-gray-50 text-[var(--text-primary)] border border-[var(--border-primary)] px-3 py-2 rounded text-xs font-bold shadow transition-all flex items-center gap-1">{isExporting ? '...' : '📄 PDF (Landscape)'}</button>
                   )}
                   {activeTab === 'personas' && (
                       <button onClick={handleDownloadPDF} className="bg-white hover:bg-gray-50 text-[var(--text-primary)] border border-[var(--border-primary)] px-3 py-2 rounded text-xs font-bold shadow transition-all flex items-center gap-1">{isExporting ? '...' : '📄 PDF (Landscape)'}</button>
                   )}
                   {(activeTab === 'journey' || activeTab === 'tech') && (
                       <button onClick={handleDownloadPDF} className="bg-white hover:bg-gray-50 text-[var(--text-primary)] border border-[var(--border-primary)] px-3 py-2 rounded text-xs font-bold shadow transition-all flex items-center gap-1">{isExporting ? '...' : '📄 PDF (Landscape)'}</button>
                   )}
                   <button onClick={onSave} className="bg-[var(--nxt-pink)] hover:bg-pink-600 text-white px-3 py-2 rounded text-xs font-bold shadow transition-all flex items-center gap-1"><span>💾</span> Save</button>
                   <button onClick={onReset} className="bg-[var(--bg-tertiary)] hover:bg-[var(--bg-primary)] text-[var(--text-primary)] border border-[var(--border-primary)] px-3 py-2 rounded text-xs font-bold shadow transition-all flex items-center gap-1 ml-2"><span>+</span> New</button>
              </div>
          </div>

          <div className="flex-1 overflow-auto p-8">
              <div ref={contentRef} className="max-w-7xl mx-auto bg-[var(--bg-primary)] p-8 rounded-2xl shadow-sm border border-[var(--border-primary)] min-h-[80vh]">

                  {/* TAB 1: PERSONAS (Enhanced Layout) */}
                  {activeTab === 'personas' && (
                      <div className="space-y-8">
                          <h2 className="text-3xl font-black mb-8 border-b pb-4">Archetypes & Personas</h2>
                          <div className="grid grid-cols-1 gap-12">
                              {(personasData || []).map((p, i) => (
                                  <div key={i} className="persona-card bg-[var(--card-bg)] border border-[var(--border-primary)] rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-shadow">
                                      <div className="grid md:grid-cols-3">
                                          {/* Left: Image */}
                                          <div className="relative aspect-square md:aspect-auto bg-[var(--bg-tertiary)] md:border-r border-[var(--border-primary)]">
