    if (aspectRatio === "1:1" || aspectRatio === "3:4") {
        // PERSONA / PORTRAIT / SPLIT SLIDE MODE
        styleDirectives = "Style: Modern, professional illustration in the style of Laci Jordan. Bold vibrant colors, flat design, clean lines, professional character representation. Context: Authentic professional user behavior.";
        negativeConstraints = "Do not include: photorealism, 3D render, cartoonish exaggeration, anime, surrealism, floating objects, abstract nonsense, messy scribbles, confusing metaphors.";
    } else {
        // SCENE / SLIDE MODE (16:9) - UPDATED STYLE
        styleDirectives = "Style: Modern, professional corporate illustration in the style of Laci Jordan. Bold vibrant colors, flat design, clean lines. Context: Business research insights. Visuals should be literal and straightforward representations of the content, not surreal metaphors.";
        negativeConstraints = "Do not include: photorealism, 3D render, dark mode, gritty texture, messy scribbles, illegible text, complex shading, clutter, cinematic lighting, surrealism, weird abstraction, confusing elements.";
    }

    // Force strict adherence to the subject matter
    const finalPrompt = `Depict specifically: ${prompt}. Ensure all visual elements are extremely related to this description. ${styleDirectives} ${negativeConstraints}`; 

    const parts: any[] = [{ text: finalPrompt }];
    if (refImageBase64) {
        const cleanBase64 = refImageBase64.includes('base64,') 
            ? refImageBase64.split('base64,')[1] 
            : refImageBase64;

        parts.unshift({
            inlineData: {
                mimeType: 'image/png',
                data: cleanBase64
            }
        });
        parts[parts.length-1].text += " Maintain strict character consistency with the reference image.";
    }

    const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: parts
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio as any,
          imageSize: "1K"
        }
      }
    }), 3, 2000, "Image Generation");

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        const mimeType = part.inlineData.mimeType || 'image/jpeg';
        return `data:${mimeType};base64,${part.inlineData.data}`;
      }
    }
  } catch (error) {
    console.warn("Image generation failed for prompt:", prompt, error);
    return undefined;
  }
  return undefined;
};

// --- VIDEO GENERATION (VEO 3) ---
export const generateSceneVideo = async (prompt: string, imageBase64?: string): Promise<string | undefined> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        let operation;

        // Clean base64 if provided
        const cleanBase64 = imageBase64?.includes('base64,') ? imageBase64.split('base64,')[1] : imageBase64;

        // Updated Video Prompt for Infographic Style
        const styleSuffix = ". Modern, professional corporate illustration animation in the style of Laci Jordan. Flat 2D motion. Bold colors. Clean and straightforward. No surrealism.";
        const fullPrompt = `Animate strictly based on this description: ${prompt}. Ensure visual relevance. ${styleSuffix}`;

        if (cleanBase64) {
             operation = await withRetry(() => ai.models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: fullPrompt,
                image: {
                    imageBytes: cleanBase64,
                    mimeType: 'image/png', 
                },
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
            }), 3, 5000, "Veo Video Generation");
        } else {
             operation = await withRetry(() => ai.models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: fullPrompt,
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
            }), 3, 5000, "Veo Video Generation");
        }

        // Poll for completion
        let retries = 0;
        while (!operation.done && retries < 30) { // Timeout after ~2.5 mins
            await new Promise(resolve => setTimeout(resolve, 5000)); // Poll every 5s
            operation = await ai.operations.getVideosOperation({operation: operation});
            retries++;
        }

        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (downloadLink) {
             // Fetch the bytes using API Key
             const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
             const blob = await response.blob();
             return URL.createObjectURL(blob);
        }
    } catch (e) {
        console.error("Veo generation failed", e);
    }
    return undefined;
};

// --- CONTENT REWRITE HELPER ---
export const rewriteSlideContent = async (slide: Slide, theme: Theme, layout: SlideLayout): Promise<Partial<Slide>> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
        REWRITE TASK:
        Take the following slide content and rewrite it to focus heavily on the Theme: "${theme.name} - ${theme.description}".

        Original Title: "${slide.title}"
        Original Content: ${JSON.stringify(slide.content)}
        Original Narrative: "${slide.narrative}"

        Target Layout: ${layout}

        Instructions:
        1. Rewrite the Title to be punchy and theme-aligned.
        2. Rewrite the Content (Bullet points) to use the language of the theme. STRICT LIMIT: Maximum 3 bullet points.
        3. Rewrite the Visual Prompt to describe an image that visualizes this theme literally and professionally.
        4. Rewrite the Narrative (Voiceover) to explain this slide through the lens of the theme.

        Output JSON only.
    `;

    const schema: Schema = {
        type: Type.OBJECT,
        properties: {
            title: { type: Type.STRING },
            content: { type: Type.ARRAY, items: { type: Type.STRING } },
            narrative: { type: Type.STRING },
            visualPrompt: { type: Type.STRING }
        },
        required: ["title", "content", "narrative", "visualPrompt"]
    };

    const response = await withRetry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: schema
        }
    }), 3, 2000, "Slide Rewrite");

    try {
        if (response.text) {
            return JSON.parse(response.text);
        }
    } catch (e) {
        console.error("Failed to parse rewrite response", e);
    }
    return {};
};

// --- GEN AI SESSION CLASS (STATEFUL) ---

export class GenAISession {
    private chatSession: Chat;
    private ai: GoogleGenAI;
    private goal: string;
    private approach: string;
    private selectedOutputs: OutputOption[];

    constructor(goal: string, approach: string, selectedOutputs: OutputOption[] = []) {
        if (!process.env.API_KEY) throw new Error("API Key Missing");
        this.goal = goal;
        this.approach = approach || "Standard Ethnographic Analysis";
        this.selectedOutputs = selectedOutputs;
        this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // Dynamic Role & Focus based on selection
        let roleDefinition = "an elite Chief Experience Officer (CXO) and Expert Ethnographer";
        let specificFocus = "";

        if (selectedOutputs.includes('JOURNEY_MAP')) {
            roleDefinition = "a Senior Service Designer and Customer Experience Architect";
            specificFocus += " Pay close attention to systems, backstage processes, and the holistic service blueprint. Map ALL actors.";
        }
        if (selectedOutputs.includes('TECH_ARCH')) {
            roleDefinition = "an Enterprise Solutions Architect";
            specificFocus += " Identify data flows, system dependencies, and technical constraints hidden in the research. Produce flat, modern system flows.";
        }
        if (selectedOutputs.includes('PRD')) {
            roleDefinition = "a Senior Product Manager";
            specificFocus += " Focus on feature definition, success metrics, prioritization, and user stories. Be deterministic.";
        }
        if (selectedOutputs.includes('ROADMAP')) {
            roleDefinition = "an Executive Product Leader (CPO/VP)";
            specificFocus += " Focus on strategic timelines (Now/Next/Later), business goals, and dependencies.";
        }
        if (selectedOutputs.includes('STRATEGIC_RECS')) {
            roleDefinition = "a Management Consultant (McKinsey/Bain style)";
            specificFocus += " Focus on high-impact, actionable business opportunities.";
        }

        const systemInstruction = `
            You are ${roleDefinition} using Gemini 3.

            CORE OBJECTIVE:
            Collaborate with the user to analyze research data. This is a MULTI-STEP process.

            RESEARCH GOAL: "${this.goal}"
            ANALYSIS APPROACH: "${this.approach}"
            REQUIRED OUTPUTS: ${this.selectedOutputs.join(', ')}

            INSTRUCTIONS:
            - Adopt the persona required for the outputs.
            ${specificFocus}

            CRITICAL TRANSPARENCY RULES:
            - Streaming Reasoning: For every step, you must first output a "methodology" string inside the JSON object.
            - The "methodology" string MUST contain [PHASE], [QUESTION], [HYPOTHESIS], [INSIGHT], or [CORRECTION] tags.
            - [INSIGHT] usage: You MUST list every specific Theme, Persona, or Key finding in the methodology string as you find it.
            - [CORRECTION] usage: If the user gives feedback, you MUST acknowledge it with a [CORRECTION] tag detailing your change.
            - Show your work. Do not hide uncertainty.
            - Citations: Always quote the source text.

            STRICT DETERMINISM:
            - Never invent Success Metrics, Timelines, or KPIs unless explicit in the source data.
            - If data is missing, state "Not explicit in source data".
            - ALWAYS provide a CITATION quote for every insight.
        `;

        this.chatSession = this.ai.chats.create({
            model: 'gemini-3-pro-preview',
            config: {
                systemInstruction: systemInstruction,
                temperature: 0.2, // Low temperature for determinism
            }
        });
    }

    // --- CONTEXT SYNC (MANUAL EDITS) ---
    async updateContext(contextLabel: string, data: any): Promise<void> {
        const prompt = `SYSTEM UPDATE: The user has MANUALLY EDITED the ${contextLabel}. Use the following JSON as the new ground truth for future steps. Forget the previous version of this data. \n\n ${JSON.stringify(data)}`;
        await withRetry(() => this.chatSession.sendMessage({ message: prompt }), 3, 1000, "Context Update");
    }

    // --- SESSION RESTORE / HYDRATION ---
    async restore(
        ingestion: StepResult_Ingestion | null,
        themes: StepResult_Themes | null,
        personas: StepResult_Personas | null,
        structure: StepResult_Structure | null
    ): Promise<void> {
        const contextPayload = {
            instruction: "SYSTEM RESTORE: Resuming saved session. The following data is the established ground truth. Do not generate new output, simply acknowledge.",
            researchContext: ingestion ? { summary: ingestion.summary, methodology: ingestion.methodology } : "Pending",
            establishedThemes: themes ? themes.themes : "Pending",
            establishedPersonas: personas ? personas.personas : "Pending",
            establishedStructure: structure ? structure.slides : "Pending"
        };

        try {
            const schema: Schema = { type: Type.OBJECT, properties: { status: { type: Type.STRING } } };
            await this.chatSession.sendMessage({
                message: [{ text: JSON.stringify(contextPayload) }],
                config: { responseMimeType: "application/json", responseSchema: schema }
            });
        } catch (e) {
            console.warn("Session restore warning (non-fatal):", e);
        }
    }

    // --- STEP 1: INGESTION & CONTEXT ---
    async ingestContext(files: FileUpload[], onStream: (t: string) => void): Promise<StepResult_Ingestion> {
        const fileParts: any[] = [];
        files.forEach((file, index) => {
            fileParts.push({ text: `--- START OF FILE ${index + 1}: "${file.name}" ---` });
            fileParts.push({ inlineData: { mimeType: file.type, data: file.data } });
            fileParts.push({ text: `--- END OF FILE ${index + 1}: "${file.name}" ---` });
        });

        const prompt = `
            STEP 1: DATA INGESTION & CONTEXT CHECK.
            Read the uploaded files. 
            TASKS:
            1. Summarize the 'World' and context found in these documents.
            2. Identify the key stakeholders or actors.
            3. Assess the data quality/type.
            4. **METADATA EXTRACTION**: For EACH file, extract the Author and Publication Date.

            Ensure your summary relates back to the RESEARCH GOAL: "${this.goal}".

            Output JSON matching this schema:
            {
                methodology: "Start with [PHASE] Data Ingestion... then [QUESTION]... then [INSIGHT] 'I have identified X as a key stakeholder'...",
                summary: "High level executive summary of the research content.",
                dataTypesIdentified: ["Interview", "Survey", "Article", etc],
                keyStakeholders: ["Patients", "Doctors", etc],
                documents: [{ fileName: "name", author: "Found Name or Unknown", publicationDate: "Date or Unknown" }],
                confidenceScore: number (0-100),
                reasoning: "Why you are confident or uncertain."
            }
        `;

        const schema: Schema = {
            type: Type.OBJECT,
            properties: {
                methodology: { type: Type.STRING },
                summary: { type: Type.STRING },
                dataTypesIdentified: { type: Type.ARRAY, items: { type: Type.STRING } },
                keyStakeholders: { type: Type.ARRAY, items: { type: Type.STRING } },
                documents: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { fileName: { type: Type.STRING }, author: { type: Type.STRING }, publicationDate: { type: Type.STRING } } } },
                confidenceScore: { type: Type.NUMBER },
                reasoning: { type: Type.STRING }
            },
            required: ["methodology", "summary", "dataTypesIdentified", "keyStakeholders", "documents", "confidenceScore"]
        };

        return await this.executeStep<StepResult_Ingestion>(prompt, schema, fileParts, onStream);
    }

