                        goals: { type: Type.ARRAY, items: { type: Type.STRING } },
                        themes: { type: Type.ARRAY, items: { type: Type.STRING } },
                        items: { type: Type.ARRAY, items: roadmapItemSchema }
                    },
                    required: ["vision", "goals", "themes", "items"]
                }
            },
            required: ["methodology", "roadmap"]
        };

        return await this.executeStep<StepResult_Roadmap>(prompt, schema, [], onStream);
    }

    // --- STEP: TECHNICAL ARCHITECTURE ---
    async generateTechArchitecture(feedback: string | undefined, onStream: (t: string) => void): Promise<StepResult_TechArch> {
