            Output JSON.
        `;

        const schema: Schema = {
            type: Type.OBJECT,
            properties: {
                methodology: { type: Type.STRING },
                architecture: {
                    type: Type.OBJECT,
                    properties: {
                        overview: { type: Type.STRING },
