                                                     {p.selectedOutputs.includes('VIDEO_SCRIPT') ? '🎬' : p.selectedOutputs.includes('STRATEGY_DECK') ? '📊' : '📄'}
                                                </div>
                                                <span className="text-[10px] font-mono text-[var(--text-tertiary)]">{new Date(p.createdAt).toLocaleDateString()}</span>
                                            </div>

                                            <h4 className="font-bold text-sm text-[var(--text-primary)] mb-1 truncate">{p.name || "Untitled Research"}</h4>
                                            <p className="text-xs text-[var(--text-secondary)] line-clamp-2 mb-3 h-8">{p.goal}</p>

                                            <div className="flex flex-wrap gap-1">
                                                {p.selectedOutputs.slice(0, 3).map(o => (
