            Based on the Themes, Pain Points and Opportunities identified in the research, propose a technical system architecture.
            Design flat, modern, minimalistic system flows.
            Define the Nodes (Users, Systems, Databases) and Flows.
            Output JSON.
        `;

        const schema: Schema = {
            type: Type.OBJECT,
            properties: {
                methodology: { type: Type.STRING },
                architecture: {
                    type: Type.OBJECT,
                    properties: {
                        overview: { type: Type.STRING },
                        nodes: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    id: { type: Type.STRING },
                                    label: { type: Type.STRING },
                                    type: { type: Type.STRING, enum: ['User', 'System', 'Database', 'External API', 'Security'] },
                                    description: { type: Type.STRING }
                                },
                                required: ["id", "label", "type"]
                            }
                        },
                        flows: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    fromId: { type: Type.STRING },
                                    toId: { type: Type.STRING },
                                    action: { type: Type.STRING },
                                    protocol: { type: Type.STRING }
                                },
                                required: ["fromId", "toId", "action"]
                            }
                        },
                        securityConsiderations: { type: Type.ARRAY, items: { type: Type.STRING } }
                    },
                    required: ["overview", "nodes", "flows"]
                }
            },
            required: ["methodology", "architecture"]
        };

        const result = await this.executeStep<StepResult_TechArch>(prompt, schema, [], onStream);

        // --- Generate Diagram Image ---
        if (result.architecture) {
            const nodesList = result.architecture.nodes.map(n => n.label).join(", ");
            const imgPrompt = `A gorgeous, professional system flow diagram visualization. White background. Clean vector lines. Nodes: ${nodesList}. Technical architecture style. No photorealism. Infographic style.`;

            try {
                const diagramUrl = await generateImage(imgPrompt, "16:9");
                result.architecture.diagramUrl = diagramUrl;
            } catch (e) {
                console.warn("Failed to generate architecture diagram image", e);
            }
        }

        return result;
    }

    // --- STEP 3.5: DECK STRUCTURE ---
    async generateDeckStructure(feedback: string | undefined, recommendations: StrategicRecommendation[] | undefined, onStream: (t: string) => void): Promise<StepResult_Structure> {
        const feedbackPrompt = feedback 
            ? `USER INTERVENTION: "${feedback}". Adjust outline.` 
            : "Plan the Strategy Deck.";

        let recsContext = "";
        if (recommendations && recommendations.length > 0) {
            recsContext = `APPROVED RECOMMENDATIONS: ${JSON.stringify(recommendations)}. Ensure the deck structure specifically includes slides to present these recommendations.`;
        }

        const prompt = `
            ${feedbackPrompt}
            ${recsContext}
            STEP: PRESENTATION ARCHITECTURE.
            Create a detailed structure for the final presentation answering the Research Goal: "${this.goal}".
            RULES: No length limit. Create 'storyArc'.
            Output JSON.
        `;

        const schema: Schema = {
            type: Type.OBJECT,
            properties: {
                methodology: { type: Type.STRING },
                storyArc: { type: Type.STRING },
                slides: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            slideNumber: { type: Type.INTEGER },
                            layout: { type: Type.STRING, enum: ['TITLE_SLIDE', 'SECTION_HEADER', 'CONTENT_SPLIT_RIGHT', 'CONTENT_SPLIT_LEFT', 'FULL_BLEED_IMAGE', 'TYPOGRAPHY_QUOTE'] },
                            title: { type: Type.STRING },
                            rationale: { type: Type.STRING }
                        },
                        required: ["slideNumber", "layout", "title", "rationale"]
                    }
                }
            },
            required: ["methodology", "storyArc", "slides"]
        };

        return await this.executeStep<StepResult_Structure>(prompt, schema, [], onStream);
    }

    // --- STEP 4: NARRATIVE & CONTENT ---
    async generateNarrative(
        structure: StepResult_Structure, 
        recommendations: StrategicRecommendation[] | undefined,
        feedback: string | undefined, 
        onStream: (t: string) => void
    ): Promise<StepResult_Narrative> {

        const slidesContext = JSON.stringify(structure.slides.map(s => ({ num: s.slideNumber, title: s.title, layout: s.layout, rationale: s.rationale })));

        let recsContext = "";
        if (recommendations && recommendations.length > 0) {
            recsContext = `CONTEXT: The user has ALREADY approved these recommendations: ${JSON.stringify(recommendations)}. Use them to inform the narrative/slides. Do NOT generate new ones.`;
        }

        const feedbackPrompt = feedback ? `USER INTERVENTION: "${feedback}".` : "Outline approved.";

        const prompt = `
            ${feedbackPrompt}
            ${recsContext}
            STEP: NARRATIVE & CONTENT.
            INPUT STRUCTURE: ${slidesContext}

            TASKS:
            1. Generate Video Script scenes. **REQUIREMENT: Create at least 15 distinct scenes to ensure a long enough video.**
            2. Generate Slides Content (STRICT LIMIT: Max 3 bullet points per slide), Narrative, and VISUAL PROMPTS.

            Output JSON.
        `;

        const schema: Schema = {
            type: Type.OBJECT,
            properties: {
                methodology: { type: Type.STRING },
                videoScript: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            sceneNumber: { type: Type.INTEGER },
                            visualDescription: { type: Type.STRING },
                            audioNarration: { type: Type.STRING },
                            durationSeconds: { type: Type.INTEGER },
                            tags: { type: Type.ARRAY, items: { type: Type.STRING } },
                            personaRef: { type: Type.STRING },
                            quote: { type: Type.STRING },
                            visualPrompt: { type: Type.STRING }
                        },
                        required: ["sceneNumber", "visualDescription", "audioNarration", "quote", "visualPrompt"]
                    }
                },
                slides: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            slideNumber: { type: Type.INTEGER },
                            layout: { type: Type.STRING, enum: ['TITLE_SLIDE', 'SECTION_HEADER', 'CONTENT_SPLIT_RIGHT', 'CONTENT_SPLIT_LEFT', 'FULL_BLEED_IMAGE', 'TYPOGRAPHY_QUOTE'] },
                            title: { type: Type.STRING },
                            content: { type: Type.ARRAY, items: { type: Type.STRING } },
                            narrative: { type: Type.STRING },
                            speakerNotes: { type: Type.STRING },
                            visualPrompt: { type: Type.STRING },
                            quote: { type: Type.STRING }
                        },
                        required: ["slideNumber", "layout", "title", "content", "narrative", "visualPrompt", "quote"]
                    }
                }
            },
            required: ["methodology", "videoScript", "slides"]
        };

        const result = await this.executeStep<StepResult_Narrative>(prompt, schema, [], onStream);

        const slidesWithStyle = (result.slides || []).map(slide => ({
            ...slide,
            style: { ...DEFAULT_STYLE }
        }));

        return { ...result, slides: slidesWithStyle };
    }

    // --- STEP 5: VISUALIZATION ---
    async visualizeNarrative(
        narrativeData: StepResult_Narrative, 
        personas: Persona[], 
        recommendations: StrategicRecommendation[],
        outputs: OutputOption[],
        onStatus: (s: string) => void, 
        onStream?: (t: string) => void
    ): Promise<StepResult_Final> {

        const scriptWithImages: ScriptScene[] = [];
        const personaMap = new Map<string, string>();
        personas.forEach(p => { if (p.imageUrl) personaMap.set(p.name, p.imageUrl); });

        const pushEvent = (type: string, content: string) => {
            if (onStream) {
                onStream(` "[methodology]": "[${type}] ${content} [${type}]" `); 
            }
        };

        pushEvent("PHASE", "Starting Visual Generation Sequence");

        // 1. Video Script Images (Only if Video Script selected)
        if (outputs.includes('VIDEO_SCRIPT')) {
            onStatus("Visualizing Storyboard...");
            for (let i = 0; i < narrativeData.videoScript.length; i++) {
                const scene = narrativeData.videoScript[i];
                onStatus(`Visualizing Scene ${i+1}/${narrativeData.videoScript.length}...`);

                const descSnippet = scene.visualDescription ? scene.visualDescription.substring(0, 30) : "Scene";
                pushEvent("INSIGHT", `Generating visual for Scene ${i+1}: ${descSnippet}...`);

                let refImage = undefined;
                if (scene.personaRef && personaMap.has(scene.personaRef)) {
                    refImage = personaMap.get(scene.personaRef);
                }
                const promptToUse = scene.visualPrompt || scene.visualDescription;
                const url = await generateImage(promptToUse, "16:9", refImage);
                scriptWithImages.push({ ...scene, imageUrl: url, videoStatus: 'idle', imageStatus: 'idle' });
            }
        }

        // 2. Strategy Deck Images (Only if Deck selected)
        let slidesWithImages: Slide[] = [];
        if (outputs.includes('STRATEGY_DECK')) {
            onStatus("Visualizing Strategy Deck...");
            pushEvent("PHASE", "Generating Strategy Deck Visuals");

            slidesWithImages = await Promise.all((narrativeData.slides || []).map(async (slide, idx) => {
                let imageUrl = undefined;
                let aspectRatio = "16:9";
                // Optimized size for split layouts
                if (slide.layout === 'CONTENT_SPLIT_RIGHT' || slide.layout === 'CONTENT_SPLIT_LEFT') {
                    aspectRatio = "1:1"; 
                }

                // Force unique image generation for every slide to prevent duplicates
                onStatus(`Generating High-Fidelity Slide Visual ${idx+1}...`);
                pushEvent("INSIGHT", `Creating high-fidelity asset for Slide ${idx+1} (${slide.layout})`);

                imageUrl = await generateImage(slide.visualPrompt, aspectRatio);

                return { ...slide, imageUrl: imageUrl, imageStatus: 'idle' as const };
            }));
        }

        pushEvent("PHASE", "Visualization Complete");

        return { 
            methodology: narrativeData.methodology,
            videoScript: scriptWithImages, 
            slides: slidesWithImages,
            recommendations: recommendations
        };
    }

    // --- GENERIC EXECUTOR ---
    private async executeStep<T>(prompt: string, schema: Schema, parts: any[] = [], onStream: (t: string) => void): Promise<T> {
        const result = await withRetry<any>(() => this.chatSession.sendMessageStream({
            message: [...parts, { text: prompt }],
            config: {
                responseMimeType: "application/json",
                responseSchema: schema
            }
        }), 3, 2000, "GenAI Step Execution");

        let fullText = "";

        // Handle result.stream if available (newer SDK pattern), or result if it IS the iterable
        // Type coercion to any to handle runtime variance
        const stream = (result.stream || result) as AsyncIterable<GenerateContentResponse>;

        try {
            for await (const chunk of stream) {
                const text = chunk.text; // Ensure we access property safely
                if (text) {
                    fullText += text;
                    onStream(fullText);
                }
            }
        } catch (streamError) {
            console.warn("Stream iteration error:", streamError);
            // If stream fails but we have some text, try to parse it. 
            // If text is empty, rethrow.
            if (!fullText) throw streamError;
        }

        // Sanitize markdown from JSON response
        const cleanedText = fullText.replace(/```json\n?|```/g, '').trim();

        if (!cleanedText) {
            throw new Error("Empty response from model");
        }

        try {
            return JSON.parse(cleanedText) as T;
        } catch (e) {
            console.error("JSON Parse Error", e);
            throw new Error("Failed to parse Gemini response");
        }
    }
}

import React, { useRef, useState } from 'react';
import { FileUpload as FileUploadType } from '../types';

interface Props {
  onFilesSelected: (files: FileUploadType[]) => void;
  isLoading: boolean;
}

const FileUpload: React.FC<Props> = ({ onFilesSelected, isLoading }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragActive, setDragActive] = useState(false);

  const handleFiles = async (files: FileList | null) => {
    if (!files) return;

    const processedFiles: FileUploadType[] = [];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const reader = new FileReader();

      const promise = new Promise<void>((resolve, reject) => {
        reader.onload = (e) => {
          if (e.target?.result) {
            const base64Data = (e.target.result as string).split(',')[1];
            processedFiles.push({
              name: file.name,
              type: file.type || 'text/plain', // Default to text if unknown
              size: file.size,
              data: base64Data
            });
            resolve();
          }
        };
        reader.onerror = reject;
      });

      reader.readAsDataURL(file);
      await promise;
    }

    onFilesSelected(processedFiles);
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFiles(e.dataTransfer.files);
    }
  };

  return (
    <div className="w-full max-w-2xl mx-auto mb-8">
      <div 
        className={`relative flex flex-col items-center justify-center w-full h-64 border rounded-xl transition-all duration-300 ease-in-out cursor-pointer overflow-hidden backdrop-blur-md shadow-sm
          ${dragActive ? 'border-[var(--nxt-pink)] bg-indigo-500/10' : 'border-[var(--border-primary)] bg-[var(--card-bg)] hover:border-[var(--nxt-pink)] hover:bg-[var(--bg-secondary)]'}
          ${isLoading ? 'opacity-50 pointer-events-none' : ''}
        `}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
      >
        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept=".pdf,.txt,.json,.md,.csv,.doc,.docx"
          className="hidden"
          onChange={(e) => handleFiles(e.target.files)}
        />

        <div className="z-10 flex flex-col items-center text-center p-6">
          <div className={`p-4 rounded-full mb-4 shadow-lg transition-colors ${dragActive ? 'bg-[var(--nxt-pink)] text-white' : 'bg-[var(--bg-tertiary)]'}`}>
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-8 w-8 ${dragActive ? 'text-white' : 'text-[var(--nxt-purple)]'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
            </svg>
          </div>
          <p className="mb-2 text-lg font-bold text-[var(--text-primary)]">
            {isLoading ? "Processing files..." : "Upload Research Data"}
          </p>
          <p className="text-sm text-[var(--text-tertiary)] max-w-sm">
            Drag & drop PDF, TXT, JSON, DOC or CSV files here.
          </p>
          <div className="mt-4 flex gap-2">
            <span className="px-2 py-1 bg-[var(--bg-primary)] border border-[var(--border-primary)] rounded text-xs text-[var(--text-tertiary)] uppercase tracking-wide">.PDF</span>
            <span className="px-2 py-1 bg-[var(--bg-primary)] border border-[var(--border-primary)] rounded text-xs text-[var(--text-tertiary)] uppercase tracking-wide">.TXT</span>
            <span className="px-2 py-1 bg-[var(--bg-primary)] border border-[var(--border-primary)] rounded text-xs text-[var(--text-tertiary)] uppercase tracking-wide">.JSON</span>
            <span className="px-2 py-1 bg-[var(--bg-primary)] border border-[var(--border-primary)] rounded text-xs text-[var(--text-tertiary)] uppercase tracking-wide">.DOCX</span>
          </div>
        </div>
      </div>
    </div>
  );
};

