                            <button onClick={() => onEdit(AnalysisStage.ROADMAP)} className="w-full py-2 text-xs font-bold bg-[var(--bg-secondary)] hover:bg-[var(--bg-tertiary)] rounded text-[var(--text-secondary)] transition-colors">Edit Roadmap</button>
                        </motion.div>
                    )}

                     {/* TECH ARCH TILE */}
                     {techArch && (
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }} className="bg-[var(--card-bg)] border border-[var(--border-primary)] rounded-xl p-6 shadow-sm group hover:border-[var(--nxt-purple)] transition-colors">
                            <div className="flex justify-between items-start mb-4 border-b border-[var(--border-secondary)] pb-4">
                                <div>
                                    <h3 className="text-lg font-bold text-[var(--text-primary)]">Architecture</h3>
                                    <div className="text-xs text-[var(--text-tertiary)]">System Design</div>
                                </div>
                                <span className="text-xl font-bold text-slate-500">{techArch.architecture.nodes.length} Nodes</span>
                            </div>
                             <div className="flex flex-wrap gap-2 mb-4">
                                {techArch.architecture.nodes.slice(0,4).map((n:any, i:number) => (
                                    <span key={i} className={`text-[10px] px-2 py-1 rounded border ${n.type==='User'?'bg-blue-50 border-blue-200':n.type==='Database'?'bg-amber-50 border-amber-200':'bg-gray-50 border-gray-200'}`}>{n.label}</span>
                                ))}
                            </div>
                            <button onClick={() => onEdit(AnalysisStage.TECH_ARCH)} className="w-full py-2 text-xs font-bold bg-[var(--bg-secondary)] hover:bg-[var(--bg-tertiary)] rounded text-[var(--text-secondary)] transition-colors">Edit Architecture</button>
                        </motion.div>
                    )}

                    {/* RECS TILE */}
                    {recommendations && (
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }} className="bg-[var(--card-bg)] border border-[var(--border-primary)] rounded-xl p-6 shadow-sm group hover:border-[var(--nxt-purple)] transition-colors">
                            <div className="flex justify-between items-start mb-4 border-b border-[var(--border-secondary)] pb-4">
                                <div>
                                    <h3 className="text-lg font-bold text-[var(--text-primary)]">Strategy</h3>
                                    <div className="text-xs text-[var(--text-tertiary)]">Opportunities</div>
                                </div>
                                <span className="text-xl font-bold text-orange-500">{recommendations.recommendations.length}</span>
                            </div>
                             <div className="space-y-2 mb-4">
                                {recommendations.recommendations.slice(0,3).map((r:any, i:number) => (
                                    <div key={i} className="text-xs truncate font-medium">• {r.title}</div>
                                ))}
                            </div>
                            <button onClick={() => onEdit(AnalysisStage.RECOMMENDATIONS)} className="w-full py-2 text-xs font-bold bg-[var(--bg-secondary)] hover:bg-[var(--bg-tertiary)] rounded text-[var(--text-secondary)] transition-colors">Refine Strategy</button>
                        </motion.div>
                    )}

                    {/* STRUCTURE TILE */}
                    {structure && (
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }} className="bg-[var(--card-bg)] border border-[var(--border-primary)] rounded-xl p-6 shadow-sm group hover:border-[var(--nxt-purple)] transition-colors">
                            <div className="flex justify-between items-start mb-4 border-b border-[var(--border-secondary)] pb-4">
                                <div>
                                    <h3 className="text-lg font-bold text-[var(--text-primary)]">Narrative Arc</h3>
                                    <div className="text-xs text-[var(--text-tertiary)]">Story Structure</div>
                                </div>
                                <span className="text-xl font-bold text-[var(--text-primary)]">{structure.slides.length} Parts</span>
                            </div>
                            <div className="space-y-1 mb-4">
                                 {structure.slides.slice(0, 3).map((s: any, i: number) => (
                                    <div key={i} className="flex justify-between text-xs p-1 bg-[var(--bg-tertiary)] rounded">
                                        <span className="truncate w-3/4">{s.title}</span>
                                        <span className="text-[10px] text-[var(--text-tertiary)]">{(s.layout || '').substring(0,4)}</span>
                                    </div>
                                 ))}
                            </div>
                            <button onClick={() => onEdit(AnalysisStage.DECK_STRUCTURE)} className="w-full py-2 text-xs font-bold bg-[var(--bg-secondary)] hover:bg-[var(--bg-tertiary)] rounded text-[var(--text-secondary)] transition-colors">Edit Outline</button>
                        </motion.div>
                    )}

                </div>
            </div>

            {/* RIGHT: Thinking Stream (Integrated) */}
            <div className="w-96 flex-shrink-0 bg-[var(--bg-secondary)] border border-[var(--border-primary)] rounded-xl flex flex-col overflow-hidden shadow-lg h-full">
                <div className="p-4 border-b border-[var(--border-primary)] bg-[var(--bg-tertiary)]">
                    <div className="flex items-center gap-2">
                        <div className={`w-2 h-2 rounded-full ${currentStatus.includes('...') ? 'bg-[var(--nxt-pink)] animate-pulse' : 'bg-green-500'}`}></div>
                        <span className="text-xs font-bold uppercase tracking-widest">Reasoning Stream</span>
                    </div>
                    <p className="text-xs text-[var(--text-tertiary)] mt-1 truncate">{currentStatus || "System Ready"}</p>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-3 font-mono text-xs">
                    <AnimatePresence>
                        {events.map((event, i) => (
                            <motion.div 
                                key={i} 
                                initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} 
                                className={`p-3 rounded border-l-2 ${
                                    event.type === 'PHASE' ? 'border-[var(--nxt-purple)] bg-[var(--nxt-purple)]/5' :
                                    event.type === 'INSIGHT' ? 'border-[var(--nxt-pink)] bg-[var(--bg-tertiary)]' :
                                    event.type === 'CORRECTION' ? 'border-amber-500 bg-amber-50' :
                                    event.type === 'INTERVENTION' ? 'border-blue-500 bg-blue-50 text-blue-900' :
                                    'border-gray-300'
                                }`}
                            >
                                <span className={`font-bold opacity-70 text-[10px] block mb-1 uppercase ${event.type === 'INTERVENTION' ? 'text-blue-600' : ''}`}>
                                    {event.type}
                                </span>
                                {event.content}
                            </motion.div>
                        ))}
                    </AnimatePresence>
                    <div ref={streamEndRef} className="h-4"></div>
                </div>
            </div>
        </div>
    );
};

// --- MAIN APP COMPONENT ---
const App = () => {
    const [appState, setAppState] = useState<AppState>(AppState.IDLE);
    const [files, setFiles] = useState<FileType[]>([]);
    const [statusMessage, setStatusMessage] = useState("");
    const [activeStage, setActiveStage] = useState<AnalysisStage>(AnalysisStage.IDLE);
    const [showMethodology, setShowMethodology] = useState<OutputOption | null>(null);
    const [selectedOutputs, setSelectedOutputs] = useState<OutputOption[]>(['PERSONAS', 'STRATEGY_DECK']);
    const [researchGoal, setResearchGoal] = useState("Identify emerging needs in the remote work sector.");
    const [analysisApproach, setAnalysisApproach] = useState("Standard Ethnographic Analysis");
    const [streamingLog, setStreamingLog] = useState<string[]>([]);
    const [thinkingEvents, setThinkingEvents] = useState<ThinkingEvent[]>([]);
    const [savedProjects, setSavedProjects] = useState<SavedProject[]>([]);
    const [notification, setNotification] = useState<string | null>(null);

    // State for Analysis Results (Intermediate & Final)
    const [result, setResult] = useState<AnalysisResult | null>(null);
    const [ingestionResult, setIngestionResult] = useState<any>(null);
    const [themesResult, setThemesResult] = useState<any>(null);
    const [personasResult, setPersonasResult] = useState<any>(null);
    const [structureResult, setStructureResult] = useState<any>(null);
    const [narrativeResult, setNarrativeResult] = useState<any>(null);
    const [journeyResult, setJourneyResult] = useState<any>(null);
    const [techResult, setTechResult] = useState<any>(null);
    const [prdResult, setPrdResult] = useState<any>(null);
    const [roadmapResult, setRoadmapResult] = useState<any>(null);
    const [recsResult, setRecsResult] = useState<any>(null);

    const sessionRef = useRef<GenAISession | null>(null);

    useEffect(() => {
        const saved = localStorage.getItem('nxt_saved_projects');
        if (saved) {
            try {
                setSavedProjects(JSON.parse(saved));
            } catch (e) {
                console.error("Failed to load saved projects", e);
            }
        }
    }, []);

    const handleStreamUpdate = (text: string) => {
        // Parse the text for specific tags [PHASE], [INSIGHT], [CORRECTION]
        const regex = /\[(PHASE|INSIGHT|CORRECTION|QUESTION|HYPOTHESIS)\] (.*?)(?=\[|$)/g;
        let match;
        while ((match = regex.exec(text)) !== null) {
            const type = match[1];
            const content = match[2].trim();
            // Check if this specific event content is already logged to avoid duplicates in the UI
            setThinkingEvents(prev => {
                const exists = prev.some(e => e.type === type && e.content === content);
                if (!exists) return [...prev, { type, content }];
                return prev;
            });
        }
    };

    const handleSaveProject = (updatedData?: AnalysisResult) => {
        // Use updatedData if provided (from child components edits), otherwise fallback to current result
        const dataToSave = updatedData || result;
        if (!dataToSave) return;

        const newProject: SavedProject = {
            id: Date.now().toString(),
            name: researchGoal || "Untitled Project",
            createdAt: Date.now(),
            goal: researchGoal,
            approach: analysisApproach,
            selectedOutputs: selectedOutputs,
            result: dataToSave,
            ingestion: ingestionResult,
            themes: themesResult,
            personas: personasResult,
            journeyMap: journeyResult,
            techArch: techResult,
            prd: prdResult,
            roadmap: roadmapResult,
            recommendations: recsResult,
            structure: structureResult,
            narrative: narrativeResult
        };

        const saveToStorage = (projects: SavedProject[]) => {
            localStorage.setItem('nxt_saved_projects', JSON.stringify(projects));
            setSavedProjects(projects);
        };

        try {
            // Attempt standard save
            saveToStorage([newProject, ...savedProjects]);
            setNotification("Project saved successfully");
            setTimeout(() => setNotification(null), 3000);
        } catch (e: any) {
            // Handle Quota Exceeded
            if (e.name === 'QuotaExceededError' || e.message?.includes('exceeded the quota')) {
                console.warn("Storage quota exceeded. Attempting to free space...");

                let currentList = [...savedProjects];
                let saved = false;

                // 1. Try removing oldest projects
                while (currentList.length > 0 && !saved) {
                    currentList.pop(); // Remove oldest
                    try {
                        saveToStorage([newProject, ...currentList]);
                        saved = true;
                        setNotification("Saved (oldest projects removed for space)");
                    } catch (evictError) {
                        // Continue loop
                    }
                }

                // 2. If still failing, strip images from the new project and save it alone/with remaining
                if (!saved) {
                    try {
                        const strippedProject = stripImages(newProject);
                        // Try saving with the stripped project
                        saveToStorage([strippedProject, ...currentList]);
                        saved = true;
                        setNotification("Saved (images removed due to space)");
                    } catch (stripError) {
                        console.error("Critical save failure", stripError);
                        setNotification("Failed to save. Storage limit exceeded.");
                    }
                }
                setTimeout(() => setNotification(null), 3000);
            } else {
                console.error("Save failed", e);
                setNotification("Failed to save project.");
                setTimeout(() => setNotification(null), 3000);
            }
        }
    };

    const handleReset = () => {
        setAppState(AppState.IDLE);
        setFiles([]);
        setResearchGoal("");
        setAnalysisApproach("Standard Ethnographic Analysis");
        setSelectedOutputs(['PERSONAS', 'STRATEGY_DECK']);
        setThinkingEvents([]);
        setResult(null);
        setIngestionResult(null);
        setThemesResult(null);
        setPersonasResult(null);
        setJourneyResult(null);
        setTechResult(null);
        setPrdResult(null);
        setRoadmapResult(null);
        setRecsResult(null);
        setStructureResult(null);
        setNarrativeResult(null);
        sessionRef.current = null;
    };

    const loadProject = async (project: SavedProject) => {
        // Hydrate State
        setResearchGoal(project.goal);
        setAnalysisApproach(project.approach);
        setSelectedOutputs(project.selectedOutputs);

        setIngestionResult(project.ingestion);
        setThemesResult(project.themes);
        setPersonasResult(project.personas);
        setJourneyResult(project.journeyMap);
        setTechResult(project.techArch);
        setPrdResult(project.prd);
        setRoadmapResult(project.roadmap);
        setRecsResult(project.recommendations);
        setStructureResult(project.structure);
        setNarrativeResult(project.narrative);
        setResult(project.result);

        // Try to Re-ignite the session for potential edits (if key is available)
        if (process.env.API_KEY) { 
             sessionRef.current = new GenAISession(project.goal, project.approach, project.selectedOutputs);
             // We don't await this to keep UI snappy, but we trigger the context injection
             sessionRef.current.restore(project.ingestion, project.themes, project.personas, project.structure);
        }

        setAppState(AppState.SUCCESS);
    };

    const deleteProject = (id: string) => {
        const updated = savedProjects.filter(p => p.id !== id);
        setSavedProjects(updated);
        localStorage.setItem('nxt_saved_projects', JSON.stringify(updated));
    };

    const startAnalysis = async () => {
        if (!process.env.API_KEY) {
            if (window.aistudio && await window.aistudio.hasSelectedApiKey()) {
                // Good
            } else if (window.aistudio) {
                await window.aistudio.openSelectKey();
                // Race condition mitigation
                await new Promise(r => setTimeout(r, 1000));
            }
        }

        setAppState(AppState.ANALYZING);
        setThinkingEvents([]);
        sessionRef.current = new GenAISession(researchGoal, analysisApproach, selectedOutputs);

        try {
            // STEP 1: Ingestion
            setStatusMessage("Reading & Contextualizing...");
            setActiveStage(AnalysisStage.INGESTION);
            const ingestion = await sessionRef.current.ingestContext(files, handleStreamUpdate);
            setIngestionResult(ingestion);
            setStatusMessage("Context verification required."); // Update to remove '...' so modal unlocks
            // Wait for user approval via Checkpoint
        } catch (e) {
            console.error(e);
            setAppState(AppState.ERROR);
            setStatusMessage("Error during analysis. Please try again.");
            setActiveStage(AnalysisStage.IDLE); // Important: Close modal on error
        }
    };

    const handleCheckpointApproval = async (feedback?: string, modifiedData?: any, interventionLog?: string) => {
        if (!sessionRef.current) return;

        // Log user intervention explicitly to the history stream
        if (interventionLog) {
             setThinkingEvents(prev => [...prev, { type: 'INTERVENTION', content: interventionLog }]);
        } else if (feedback) {
             setThinkingEvents(prev => [...prev, { type: 'INTERVENTION', content: feedback }]);
        } else if (modifiedData) {
             setThinkingEvents(prev => [...prev, { type: 'INTERVENTION', content: "Manual Data Edits Applied" }]);
        }

        // CRITICAL UPDATE: If this is an approval (no feedback triggering regeneration),
        // we close the modal IMMEDIATELY to give instant responsiveness, while the async operations happen in background.
        // If feedback exists, we keep the modal open to show the "Regenerating..." state.
        if (!feedback) {
            setActiveStage(AnalysisStage.IDLE);
        }

        try {
            // IF EDITING FROM FINAL VIEW
            if (appState === AppState.SUCCESS) {
                console.log("Saving edits from Results View...", activeStage);
                if (modifiedData) {
                    if (activeStage === AnalysisStage.PERSONAS) {
                         setPersonasResult(modifiedData);
                         setResult((prev: any) => ({ ...prev, personas: modifiedData.personas }));
                         await sessionRef.current.updateContext("Personas", modifiedData);
                    } else if (activeStage === AnalysisStage.THEMES) {
                         setThemesResult(modifiedData);
                         setResult((prev: any) => ({ ...prev, themes: modifiedData.themes }));
                         await sessionRef.current.updateContext("Themes", modifiedData);
                    } else if (activeStage === AnalysisStage.JOURNEY_MAP) {
                         setJourneyResult(modifiedData);
                         setResult((prev: any) => ({ ...prev, journeyMap: modifiedData.stages }));
                         // Trigger image regeneration for diagram?
                         if (modifiedData.stages) {
                            const resultWithDiagram = await sessionRef.current.generateJourneyMap("Regenerate diagram only based on updated stages");
                             setJourneyResult((prev:any) => ({...prev, diagramUrl: resultWithDiagram.diagramUrl}));
                             setResult((prev: any) => ({ ...prev, journeyMap: modifiedData.stages, journeyMapDiagramUrl: resultWithDiagram.diagramUrl }));
                         }
                    } else if (activeStage === AnalysisStage.PRD) {
                        setPrdResult(modifiedData);
                        setResult((prev: any) => ({ ...prev, prd: modifiedData.prd }));
                    } else if (activeStage === AnalysisStage.ROADMAP) {
                        setRoadmapResult(modifiedData);
                        setResult((prev: any) => ({ ...prev, roadmap: modifiedData.roadmap }));
                    } else if (activeStage === AnalysisStage.TECH_ARCH) {
                        setTechResult(modifiedData);
                        setResult((prev: any) => ({ ...prev, techArchitecture: modifiedData.architecture }));
                        // Trigger image regeneration
                         if (modifiedData.architecture) {
                            const resultWithDiagram = await sessionRef.current.generateTechArchitecture("Regenerate diagram only");
                             setTechResult((prev:any) => ({...prev, architecture: {...prev.architecture, diagramUrl: resultWithDiagram.architecture.diagramUrl}}));
                             setResult((prev: any) => ({ ...prev, techArchitecture: { ...modifiedData.architecture, diagramUrl: resultWithDiagram.architecture.diagramUrl } }));
                         }
                    } else if (activeStage === AnalysisStage.RECOMMENDATIONS) {
                        setRecsResult(modifiedData);
                        setResult((prev: any) => ({ ...prev, recommendations: modifiedData.recommendations }));
                    } else if (activeStage === AnalysisStage.DECK_STRUCTURE) {
                        setStructureResult(modifiedData);
                        // No result update here usually unless we regenerate content
                    } else if (activeStage === AnalysisStage.NARRATIVE) {
                        setNarrativeResult(modifiedData);
                        // Trigger visual regen? For now just save text.
                    }
                }

                // If we didn't already close it above (unlikely in success edit flow, but for safety)
                if (feedback) setActiveStage(AnalysisStage.IDLE); 
                return;
            }

            // --- STANDARD LINEAR FLOW ---

            if (activeStage === AnalysisStage.INGESTION) {
                // Ingestion typically moves forward to Themes even with feedback
                setStatusMessage("Identifying Patterns...");
                const themes = await sessionRef.current.generateThemes(feedback, handleStreamUpdate);
                setThemesResult(themes);
                setStatusMessage("Themes Identified"); // Unlock modal
                setActiveStage(AnalysisStage.THEMES);
            } 
            else if (activeStage === AnalysisStage.THEMES) {
                // If modified themes, update context
                if (modifiedData) {
                    setThemesResult(modifiedData);
                    await sessionRef.current.updateContext("Themes", modifiedData);
                }

                // REGENERATION CHECK: If feedback provided, regenerate THEMES and stay
                if (feedback) {
                    setStatusMessage("Refining Themes...");
                    const themes = await sessionRef.current.generateThemes(feedback, handleStreamUpdate);
                    setThemesResult(themes);
                    setStatusMessage("Themes Refined");
                    return; // Stay on this stage
                }

                // Branch Logic based on selectedOutputs
                if (selectedOutputs.includes('PERSONAS')) {
                    setStatusMessage("Synthesizing Personas...");
                    const personas = await sessionRef.current.generatePersonas(themesResult, undefined, handleStreamUpdate, setStatusMessage);
                    setPersonasResult(personas);
                    setStatusMessage("Personas Generated"); // Unlock modal
                    setActiveStage(AnalysisStage.PERSONAS);
                } else {
                    // Skip to next relevant stage
                    advanceToNextStage();
                }
            } 
            else if (activeStage === AnalysisStage.PERSONAS) {
                 if (modifiedData) {
                    setPersonasResult(modifiedData);
                    await sessionRef.current.updateContext("Personas", modifiedData);
                }

                // REGENERATION CHECK
                if (feedback) {
                    setStatusMessage("Refining Personas...");
                    const personas = await sessionRef.current.generatePersonas(themesResult, feedback, handleStreamUpdate, setStatusMessage);
                    setPersonasResult(personas);
                    setStatusMessage("Personas Refined");
                    return;
                }

                advanceToNextStage();
            }
            // ... Handling other parallel branches ...
            else if (activeStage === AnalysisStage.JOURNEY_MAP) {
                if (modifiedData) { setJourneyResult(modifiedData); await sessionRef.current.updateContext("Service Blueprint", modifiedData); }
                if (feedback) {
                    setStatusMessage("Refining Blueprint...");
                    const map = await sessionRef.current.generateJourneyMap(feedback, handleStreamUpdate);
                    setJourneyResult(map);
                    setStatusMessage("Blueprint Refined");
                    return;
                }
                advanceToNextStage();
            }
            else if (activeStage === AnalysisStage.PRD) {
                if (modifiedData) { setPrdResult(modifiedData); await sessionRef.current.updateContext("PRD", modifiedData); }
                if (feedback) {
                    setStatusMessage("Refining PRD...");
                    const prd = await sessionRef.current.generatePRD(feedback, handleStreamUpdate);
                    setPrdResult(prd);
                    setStatusMessage("PRD Refined");
                    return;
                }
                advanceToNextStage();
            }
            else if (activeStage === AnalysisStage.ROADMAP) {
                if (modifiedData) { setRoadmapResult(modifiedData); await sessionRef.current.updateContext("Roadmap", modifiedData); }
                if (feedback) {
                    setStatusMessage("Refining Roadmap...");
                    const map = await sessionRef.current.generateRoadmap(feedback, handleStreamUpdate);
                    setRoadmapResult(map);
                    setStatusMessage("Roadmap Refined");
                    return;
                }
                advanceToNextStage();
            }
            else if (activeStage === AnalysisStage.TECH_ARCH) {
                 if (modifiedData) { setTechResult(modifiedData); await sessionRef.current.updateContext("Architecture", modifiedData); }
                 if (feedback) {
                    setStatusMessage("Refining Architecture...");
                    const arch = await sessionRef.current.generateTechArchitecture(feedback, handleStreamUpdate);
                    setTechResult(arch);
                    setStatusMessage("Architecture Refined");
                    return;
                }
                advanceToNextStage();
            }
            else if (activeStage === AnalysisStage.RECOMMENDATIONS) {
                 if (modifiedData) { setRecsResult(modifiedData); await sessionRef.current.updateContext("Recommendations", modifiedData); }
                 if (feedback) {
                    setStatusMessage("Refining Strategy...");
                    const recs = await sessionRef.current.generateRecommendations(feedback, handleStreamUpdate);
                    setRecsResult(recs);
                    setStatusMessage("Strategy Refined");
                    return;
                }
                advanceToNextStage();
            }
            // ... Final Assembly Stages ...
            else if (activeStage === AnalysisStage.DECK_STRUCTURE) {
                if (modifiedData) setStructureResult(modifiedData);

                if (feedback) {
                    setStatusMessage("Refining Structure...");
                    const struct = await sessionRef.current.generateDeckStructure(feedback, recsResult?.recommendations, handleStreamUpdate);
                    setStructureResult(struct);
                    setStatusMessage("Structure Refined");
                    return;
                }

                setStatusMessage("Drafting Narrative & Content...");

                // 1. Generate Narrative Content
                const narrative = await sessionRef.current.generateNarrative(modifiedData || structureResult, recsResult?.recommendations, undefined, handleStreamUpdate);
                setNarrativeResult(narrative);

                // 2. IMMEDIATE VISUALIZATION (SKIP Narrative Checkpoint)
                setStatusMessage("Generating High-Fidelity Assets...");
                const final = await sessionRef.current.visualizeNarrative(
                    narrative, 
                    personasResult?.personas || [], 
                    recsResult?.recommendations || [],
                    selectedOutputs,
                    setStatusMessage, 
                    handleStreamUpdate
                );

                // Consolidate everything into Final Result
                setResult({
                    methodology: final.methodology,
                    selectedOutputs: selectedOutputs,
                    themes: themesResult?.themes || [],
                    personas: personasResult?.personas || [],
                    videoScript: final.videoScript,
                    slides: final.slides,
                    recommendations: recsResult?.recommendations || [],
                    journeyMap: journeyResult?.stages,
                    journeyMapDiagramUrl: journeyResult?.diagramUrl,
                    techArchitecture: techResult?.architecture,
                    prd: prdResult?.prd,
                    roadmap: roadmapResult?.roadmap
                });
                setAppState(AppState.SUCCESS);
            }
            // Narrative stage block effectively unused for standard flow but kept for safety
            else if (activeStage === AnalysisStage.NARRATIVE) {
                if (modifiedData) setNarrativeResult(modifiedData);

                setStatusMessage("Generating High-Fidelity Assets...");

                const final = await sessionRef.current.visualizeNarrative(
                    modifiedData || narrativeResult, 
                    personasResult?.personas || [], 
                    recsResult?.recommendations || [],
                    selectedOutputs,
                    setStatusMessage, 
                    handleStreamUpdate
                );

                setResult({
                    methodology: final.methodology,
                    selectedOutputs: selectedOutputs,
                    themes: themesResult?.themes || [],
                    personas: personasResult?.personas || [],
                    videoScript: final.videoScript,
                    slides: final.slides,
                    recommendations: recsResult?.recommendations || [],
                    journeyMap: journeyResult?.stages,
                    journeyMapDiagramUrl: journeyResult?.diagramUrl,
                    techArchitecture: techResult?.architecture,
                    prd: prdResult?.prd,
                    roadmap: roadmapResult?.roadmap
                });
                setAppState(AppState.SUCCESS);
            }
        } catch (e) {
            console.error(e);
            setAppState(AppState.ERROR);
        }
    };

    const advanceToNextStage = async () => {
        // Simple state machine to determine next step based on `selectedOutputs` and what's already done

        // 1. Journey Map
        if (selectedOutputs.includes('JOURNEY_MAP') && !journeyResult) {
            setStatusMessage("Mapping Service Blueprint...");
            const map = await sessionRef.current?.generateJourneyMap(undefined, handleStreamUpdate);
            setJourneyResult(map);
            setStatusMessage("Blueprint Ready"); // Unlock
            setActiveStage(AnalysisStage.JOURNEY_MAP);
            return;
        }

        // 2. PRD
        if (selectedOutputs.includes('PRD') && !prdResult) {
            setStatusMessage("Defining Product Requirements...");
            const prd = await sessionRef.current?.generatePRD(undefined, handleStreamUpdate);
            setPrdResult(prd);
            setStatusMessage("PRD Drafted"); // Unlock
            setActiveStage(AnalysisStage.PRD);
            return;
        }

        // 3. Roadmap (Dependencies: PRD)
        if (selectedOutputs.includes('ROADMAP') && !roadmapResult) {
            setStatusMessage("Planning Strategic Roadmap...");
            const map = await sessionRef.current?.generateRoadmap(undefined, handleStreamUpdate);
            setRoadmapResult(map);
            setStatusMessage("Roadmap Drafted"); // Unlock
            setActiveStage(AnalysisStage.ROADMAP);
            return;
        }

        // 4. Tech Arch
        if (selectedOutputs.includes('TECH_ARCH') && !techResult) {
            setStatusMessage("Architecting Solution...");
            const arch = await sessionRef.current?.generateTechArchitecture(undefined, handleStreamUpdate);
            setTechResult(arch);
            setStatusMessage("Architecture Drafted"); // Unlock
            setActiveStage(AnalysisStage.TECH_ARCH);
            return;
        }

        // 5. Recommendations
        if (selectedOutputs.includes('STRATEGIC_RECS') && !recsResult) {
            setStatusMessage("Formulating Strategy...");
            const recs = await sessionRef.current?.generateRecommendations(undefined, handleStreamUpdate);
            setRecsResult(recs);
            setStatusMessage("Strategy Drafted"); // Unlock
            setActiveStage(AnalysisStage.RECOMMENDATIONS);
            return;
        }

        // 6. Deck Structure (If Deck or Script selected)
        if ((selectedOutputs.includes('STRATEGY_DECK') || selectedOutputs.includes('VIDEO_SCRIPT')) && !structureResult) {
            setStatusMessage("Architecting Presentation...");
            const struct = await sessionRef.current?.generateDeckStructure(undefined, recsResult?.recommendations, handleStreamUpdate);
            setStructureResult(struct);
            setStatusMessage("Structure Drafted"); // Unlock
            setActiveStage(AnalysisStage.DECK_STRUCTURE);
            return;
        }

        // If we are here, we are done with intermediate steps or just have a subset that doesn't include deck
        if (!selectedOutputs.includes('STRATEGY_DECK') && !selectedOutputs.includes('VIDEO_SCRIPT')) {
             setResult({
                methodology: "Direct Assembly",
                selectedOutputs: selectedOutputs,
                themes: themesResult?.themes || [],
                personas: personasResult?.personas || [],
                recommendations: recsResult?.recommendations || [],
                journeyMap: journeyResult?.stages,
                journeyMapDiagramUrl: journeyResult?.diagramUrl,
                techArchitecture: techResult?.architecture,
                prd: prdResult?.prd,
                roadmap: roadmapResult?.roadmap
            });
            setAppState(AppState.SUCCESS);
        }
    };

    const toggleOutput = (opt: OutputOption) => {
        if (selectedOutputs.includes(opt)) {
            setSelectedOutputs(selectedOutputs.filter(o => o !== opt));
        } else {
            setSelectedOutputs([...selectedOutputs, opt]);
        }
    };

    return (
        <div className="min-h-screen bg-[var(--bg-primary)] text-[var(--text-primary)] transition-colors duration-300 font-sans selection:bg-[var(--nxt-pink)] selection:text-white relative">

            {/* Header */}
            {appState !== AppState.SUCCESS && (
                <header className="fixed top-0 w-full z-40 bg-[var(--bg-secondary)]/80 backdrop-blur-md border-b border-[var(--border-primary)]">
                    <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
                        <Logo />
                    </div>
                </header>
            )}

            <main className={`transition-all duration-500 ${appState !== AppState.SUCCESS ? 'pt-24 px-6' : ''}`}>

                {/* IDLE STATE */}
                {appState === AppState.IDLE && (
                    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="max-w-3xl mx-auto space-y-12 pb-20">
                        <div className="text-center space-y-4">
                            <h1 className="text-5xl font-black tracking-tight leading-tight">
                                Humans in Control <span className="gradient-text">Research System</span>
                            </h1>
                            <p className="text-xl text-[var(--text-secondary)] max-w-2xl mx-auto font-light">
                                Upload unstructured data. Define your lens. <br/>
                                Generate <span className="font-semibold">verified</span> personas, strategies, and storyboards.
                            </p>
                        </div>

                        <div className="bg-[var(--card-bg)] p-8 rounded-2xl border border-[var(--border-primary)] shadow-xl space-y-8">
                            {/* Inputs */}
                            <div className="space-y-4">
                                <div>
                                    <label className="text-xs font-bold uppercase tracking-widest text-[var(--text-tertiary)] mb-2 block">Research Goal</label>
                                    <input 
                                        type="text" 
                                        value={researchGoal}
                                        onChange={(e) => setResearchGoal(e.target.value)}
                                        className="w-full bg-[var(--input-bg)] border border-[var(--border-primary)] p-4 rounded-xl text-lg focus:ring-2 focus:ring-[var(--nxt-pink)] outline-none transition-all shadow-inner"
                                        placeholder="e.g. Understand the barriers to EV adoption..."
                                    />
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                     <div>
                                        <label className="text-xs font-bold uppercase tracking-widest text-[var(--text-tertiary)] mb-2 block">Analysis Methodology/Approach</label>
                                        <input
                                            type="text"
                                            value={analysisApproach}
                                            onChange={(e) => setAnalysisApproach(e.target.value)}
                                            className="w-full bg-[var(--input-bg)] border border-[var(--border-primary)] p-4 rounded-xl text-sm outline-none shadow-inner focus:ring-2 focus:ring-[var(--nxt-pink)] transition-all"
                                            placeholder="e.g. Standard Ethnographic Analysis..."
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* Outputs Selection */}
                            <div>
                                <label className="text-xs font-bold uppercase tracking-widest text-[var(--text-tertiary)] mb-3 block">Required Outputs</label>
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                                    {Object.keys(METHODOLOGY_INFO).map((key) => (
                                        <div key={key} className="relative group">
                                            <button 
                                                onClick={() => toggleOutput(key as OutputOption)}
                                                className={`w-full p-3 rounded-lg border text-xs font-bold transition-all h-full flex flex-col items-center justify-center gap-2 text-center
                                                    ${selectedOutputs.includes(key as OutputOption) 
                                                        ? 'border-[var(--nxt-pink)] bg-[var(--nxt-pink)]/5 text-[var(--text-primary)] shadow-md' 
                                                        : 'border-[var(--border-primary)] bg-[var(--bg-tertiary)] text-[var(--text-tertiary)] hover:border-[var(--text-tertiary)]'
                                                    }`}
                                            >
                                                <span>{METHODOLOGY_INFO[key as OutputOption].title}</span>
                                            </button>
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); setShowMethodology(key as OutputOption); }}
                                                className="absolute top-1 right-1 w-4 h-4 rounded-full bg-gray-200 text-[8px] text-gray-600 flex items-center justify-center hover:bg-gray-300 opacity-0 group-hover:opacity-100 transition-opacity"
                                            >
                                                i
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            <FileUpload onFilesSelected={(newFiles) => setFiles([...files, ...newFiles])} isLoading={false} />

                            {files.length > 0 && (
                                <div className="grid gap-2 mb-2">
                                    {files.map((file, idx) => (
                                        <div key={idx} className="flex items-center justify-between p-3 bg-[var(--bg-tertiary)] rounded-lg border border-[var(--border-secondary)]">
                                            <div className="flex items-center gap-3 overflow-hidden">
                                                <span className="text-xl flex-shrink-0">📄</span>
                                                <div className="overflow-hidden">
                                                    <div className="text-sm font-bold text-[var(--text-primary)] truncate">{file.name}</div>
                                                    <div className="text-[10px] text-[var(--text-tertiary)] uppercase flex gap-2">
                                                        <span>{file.type || 'Unknown Type'}</span>
                                                        <span>•</span>
                                                        <span>{(file.size / 1024).toFixed(0)} KB</span>
                                                    </div>
                                                </div>
                                            </div>
                                            <button 
                                                onClick={() => setFiles(files.filter((_, i) => i !== idx))} 
                                                className="w-6 h-6 flex items-center justify-center rounded-full hover:bg-red-100 text-gray-400 hover:text-red-500 transition-colors"
                                            >
                                                ✕
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            )}

                            <button 
                                onClick={startAnalysis}
                                disabled={files.length === 0}
                                className={`w-full py-4 rounded-xl font-bold text-lg text-white shadow-lg transition-all transform active:scale-95
                                    ${files.length > 0 ? 'btn-primary' : 'bg-gray-300 cursor-not-allowed'}
                                `}
                            >
                                Begin Analysis Sequence
                            </button>
                        </div>

                        {/* SAVED PROJECTS */}
                        {savedProjects.length > 0 && (
                            <div className="max-w-3xl mx-auto mt-16 animate-fade-in">
                                <div className="flex items-center gap-3 mb-6">
                                     <div className="h-px bg-[var(--border-primary)] flex-1"></div>
                                     <span className="text-xs font-bold uppercase text-[var(--text-tertiary)] tracking-widest">Recent Investigations</span>
                                     <div className="h-px bg-[var(--border-primary)] flex-1"></div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {savedProjects.map((p) => (
                                        <div 
                                            key={p.id} 
                                            onClick={() => loadProject(p)}
                                            className="group bg-[var(--card-bg)] p-5 rounded-xl border border-[var(--border-primary)] hover:border-[var(--nxt-pink)] cursor-pointer transition-all shadow-sm hover:shadow-md relative overflow-hidden"
                                        >
                                            <div className="absolute top-0 right-0 p-3 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button 
                                                    onClick={(e) => { e.stopPropagation(); deleteProject(p.id); }}
                                                    className="text-xs text-red-400 hover:text-red-600 font-bold"
                                                >
                                                    DELETE
                                                </button>
                                            </div>
                                            <h4 className="font-bold text-sm text-[var(--text-primary)] mb-1 truncate">{p.name}</h4>
                                            <p className="text-xs text-[var(--text-secondary)] line-clamp-2">{p.goal}</p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}
                    </motion.div>
                )}

                {/* ANALYZING STATE */}
                {appState === AppState.ANALYZING && (
                    <LiveResearchBoard 
                        ingestion={ingestionResult}
                        themes={themesResult}
                        personas={personasResult}
                        journeyMap={journeyResult}
                        prd={prdResult}
                        roadmap={roadmapResult}
                        techArch={techResult}
                        recommendations={recsResult}
                        structure={structureResult}
                        events={thinkingEvents}
                        currentStatus={statusMessage}
                        onEdit={(stage) => setActiveStage(stage)}
                   />
                )}

                {/* RESULTS STATE */}
                {appState === AppState.SUCCESS && result && (
                    <ResultsView result={result} onReset={handleReset} onSave={handleSaveProject} onEdit={(stage) => setActiveStage(stage)} />
                )}

            </main>

            {/* NOTIFICATION TOAST */}
            <AnimatePresence>
                {notification && (
                    <motion.div 
                        initial={{ opacity: 0, y: 50, x: "-50%" }} 
                        animate={{ opacity: 1, y: 0, x: "-50%" }} 
                        exit={{ opacity: 0, y: 50, x: "-50%" }}
                        className="fixed bottom-8 left-1/2 transform -translate-x-1/2 bg-[var(--text-primary)] text-[var(--bg-primary)] px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 z-[100]"
                    >
                        <span className="font-bold text-sm">{notification}</span>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* MODALS */}
            <AnimatePresence>
                {activeStage !== AnalysisStage.IDLE && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
                        <AnalysisCheckpoint 
                            stage={activeStage}
                            data={
                                activeStage === AnalysisStage.INGESTION ? ingestionResult :
                                activeStage === AnalysisStage.THEMES ? themesResult :
                                activeStage === AnalysisStage.PERSONAS ? personasResult :
                                activeStage === AnalysisStage.JOURNEY_MAP ? journeyResult :
                                activeStage === AnalysisStage.PRD ? prdResult :
                                activeStage === AnalysisStage.ROADMAP ? roadmapResult :
                                activeStage === AnalysisStage.TECH_ARCH ? techResult :
                                activeStage === AnalysisStage.RECOMMENDATIONS ? recsResult :
                                activeStage === AnalysisStage.DECK_STRUCTURE ? structureResult :
                                activeStage === AnalysisStage.NARRATIVE ? narrativeResult : null
                            }
                            isProcessing={statusMessage.includes('...')}
                            onApprove={handleCheckpointApproval}
                            onClose={() => setActiveStage(AnalysisStage.IDLE)}
                            currentLog={thinkingEvents[thinkingEvents.length - 1]?.content}
                        />
                    </div>
                )}

                {showMethodology && (
                    <MethodologyModal outputId={showMethodology} onClose={() => setShowMethodology(null)} />
                )}
            </AnimatePresence>

        </div>
    );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { AnalysisStage, StepResult_Ingestion, StepResult_Themes, StepResult_Personas, StepResult_Structure, StepResult_Narrative, StepResult_JourneyMap, StepResult_TechArch, StepResult_PRD, StepResult_Roadmap, StepResult_Recommendations, Slide, Theme, Persona, ScriptScene, ServiceBlueprintStage, PRDFeature, RoadmapItem, StrategicRecommendation } from '../types';

interface Props {
  stage: AnalysisStage;
  data: any;
  isProcessing: boolean;
  onApprove: (feedback?: string, modifiedData?: any, interventionDetails?: string) => void;
  onClose?: () => void;
  currentLog?: string;
}

// Internal Loading Component for Initial States
const LoadingView = ({ log, elapsed }: { log?: string, elapsed: number }) => (
    <div className="flex flex-col items-center justify-center h-full p-12 space-y-8 animate-fade-in w-full">
        <div className="relative">
            <div className="w-20 h-20 border-4 border-[var(--border-secondary)] rounded-full"></div>
            <div className="absolute top-0 left-0 w-20 h-20 border-4 border-[var(--nxt-pink)] border-t-transparent rounded-full animate-spin"></div>
            <div className="absolute inset-0 flex items-center justify-center font-mono text-lg font-bold text-[var(--nxt-purple)]">
                {elapsed}s
            </div>
        </div>
        <div className="text-center space-y-3">
            <h3 className="text-2xl font-bold">Analyzing Research Data...</h3>
            <p className="text-[var(--text-secondary)] text-sm max-w-md mx-auto leading-relaxed">
                Gemini 3 Pro is performing deep reasoning on your documents. <br/>
                <span className="opacity-70">This ensures high-fidelity context extraction.</span>
            </p>
        </div>
        <div className="bg-[var(--bg-tertiary)] p-4 rounded-xl max-w-lg w-full border border-[var(--border-secondary)] shadow-inner">
             <div className="flex items-center gap-2 mb-2 border-b border-[var(--border-secondary)] pb-2">
                 <div className="w-2 h-2 rounded-full bg-[var(--nxt-pink)] animate-pulse"></div>
                 <div className="text-[10px] uppercase font-bold text-[var(--text-tertiary)]">Live Reasoning Trace</div>
             </div>
             <div className="font-mono text-xs text-[var(--text-primary)] min-h-[3rem] flex items-center justify-center text-center opacity-80 break-words line-clamp-3">
                 {log ? log.replace(/\[.*?\]/g, '').trim() : "Initializing reasoning engine..."}
             </div>
        </div>
    </div>
);

const AnalysisCheckpoint: React.FC<Props> = ({ stage, data, isProcessing, onApprove, onClose, currentLog }) => {
  const [feedback, setFeedback] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Timer for Loading State
  const [elapsed, setElapsed] = useState(0);

  useEffect(() => {
    let interval: any;
    // Start timer if processing OR if data is missing (initial load)
    if (isProcessing || !data) {
        interval = setInterval(() => {
            setElapsed(prev => prev + 1);
        }, 1000);
    } else {
        setElapsed(0);
    }
    return () => clearInterval(interval);
  }, [isProcessing, data]);

  // Local state for editing 
  const [editedThemes, setEditedThemes] = useState<Theme[]>([]);
  const [editedPersonas, setEditedPersonas] = useState<Persona[]>([]);
  const [editedNarrative, setEditedNarrative] = useState<StepResult_Narrative | null>(null);
  const [editedStructure, setEditedStructure] = useState<StepResult_Structure | null>(null);
  const [editedJourney, setEditedJourney] = useState<StepResult_JourneyMap | null>(null);
  const [editedArch, setEditedArch] = useState<StepResult_TechArch | null>(null);
  const [editedPRD, setEditedPRD] = useState<StepResult_PRD | null>(null);
  const [editedRoadmap, setEditedRoadmap] = useState<StepResult_Roadmap | null>(null);
  const [editedRecs, setEditedRecs] = useState<StepResult_Recommendations | null>(null);

  const [expandedPersona, setExpandedPersona] = useState<number | null>(null);
  const [narrativeTab, setNarrativeTab] = useState<'script' | 'slides'>('script');
  const [hasEdits, setHasEdits] = useState(false);

  // Track specific edits for logging
  const [editLog, setEditLog] = useState<string[]>([]);

  const prevDataRef = useRef<any>(null);

  useEffect(() => {
      setFeedback('');
      setHasEdits(false);
      setEditLog([]);
      setIsSubmitting(false);

      if (!data) return;

      const currentDataStr = JSON.stringify(data);
      const prevDataStr = prevDataRef.current ? JSON.stringify(prevDataRef.current) : "";

      if (currentDataStr === prevDataStr && prevDataRef.current !== null) {
          return;
      }

      prevDataRef.current = data;

      try {
          if (stage === AnalysisStage.THEMES) {
              const d = data as StepResult_Themes;
              if (d.themes && Array.isArray(d.themes)) {
                  setEditedThemes(d.themes.map(t => ({...t, status: t.status || 'approved'})));
              }
          }
          else if (stage === AnalysisStage.PERSONAS) {
              const d = data as StepResult_Personas;
              if (d.personas && Array.isArray(d.personas)) {
                  setEditedPersonas(JSON.parse(JSON.stringify(d.personas)));
                  if (d.personas.length > 0) setExpandedPersona(0);
              }
          }
          else if (stage === AnalysisStage.DECK_STRUCTURE) {
              setEditedStructure(JSON.parse(JSON.stringify(data)));
          } 
          else if (stage === AnalysisStage.NARRATIVE) {
              const nar = JSON.parse(JSON.stringify(data)) as StepResult_Narrative;
              setEditedNarrative(nar);
              if ((!nar.videoScript || nar.videoScript.length === 0) && nar.slides?.length > 0) {
                  setNarrativeTab('slides');
              } else {
                  setNarrativeTab('script');
              }
          } 
          else if (stage === AnalysisStage.JOURNEY_MAP) {
              setEditedJourney(JSON.parse(JSON.stringify(data)));
          } 
          else if (stage === AnalysisStage.TECH_ARCH) {
              setEditedArch(JSON.parse(JSON.stringify(data)));
          } 
          else if (stage === AnalysisStage.PRD) {
              setEditedPRD(JSON.parse(JSON.stringify(data)));
          } 
          else if (stage === AnalysisStage.ROADMAP) {
              setEditedRoadmap(JSON.parse(JSON.stringify(data)));
          } 
          else if (stage === AnalysisStage.RECOMMENDATIONS) {
              setEditedRecs(JSON.parse(JSON.stringify(data)));
          }
      } catch (e) {
          console.error("Error initializing checkpoint data", e);
      }
  }, [data, stage]);

  const logEdit = (desc: string) => {
      setHasEdits(true);
      if (!editLog.includes(desc)) {
          setEditLog(prev => [...prev, desc]);
      }
  };

  // --- EDITOR FUNCTIONS ---

  const toggleThemeStatus = (index: number, status: 'approved' | 'skipped' | 'priority') => {
      const newThemes = [...editedThemes];
      if (newThemes[index]) { 
          newThemes[index].status = status; 
          setEditedThemes(newThemes); 
          logEdit(`Changed Theme '${newThemes[index].name}' to ${status}`);
      }
  };

  const updatePersona = (index: number, field: keyof Persona, value: string) => {
      const newPersonas = [...editedPersonas];
      if (newPersonas[index]) { 
          (newPersonas[index] as any)[field] = value; 
          setEditedPersonas(newPersonas); 
          logEdit(`Edited Persona '${newPersonas[index].name}' ${field}`);
      }
  };

  const updatePersonaFiveW = (index: number, key: string, value: string) => {
      const newPersonas = [...editedPersonas];
      if (newPersonas[index] && newPersonas[index].fiveWs) { 
          (newPersonas[index].fiveWs as any)[key] = value; 
          setEditedPersonas(newPersonas); 
          logEdit(`Edited Persona '${newPersonas[index].name}' 5Ws (${key})`);
      }
  };

  const updateJourneyStage = (index: number, field: keyof ServiceBlueprintStage, value: string) => {
      if (!editedJourney) return;
      const newStages = [...editedJourney.stages];
      (newStages[index] as any)[field] = value;
      setEditedJourney({...editedJourney, stages: newStages});
      logEdit(`Modified Blueprint Stage ${index+1}: ${field}`);
  };

  const updatePRDField = (field: string, value: string) => {
      if (!editedPRD) return;
      const newPRD = { ...editedPRD.prd, [field]: value };
      setEditedPRD({ ...editedPRD, prd: newPRD });
      logEdit(`Updated PRD: ${field}`);
  };

  const updatePRDListField = (field: string, value: string) => {
      if (!editedPRD) return;
      const list = value.split('\n');
      const newPRD = { ...editedPRD.prd, [field]: list };
      setEditedPRD({ ...editedPRD, prd: newPRD });
      logEdit(`Updated PRD List: ${field}`);
  };

  const updatePRDFeature = (index: number, field: keyof PRDFeature, value: string) => {
      if (!editedPRD) return;
      const newFeatures = [...editedPRD.prd.features];
      (newFeatures[index] as any)[field] = value;
      setEditedPRD({ ...editedPRD, prd: { ...editedPRD.prd, features: newFeatures } });
      logEdit(`Edited Feature '${newFeatures[index].name}'`);
  };

  const updateRoadmapItem = (index: number, field: keyof RoadmapItem, value: string) => {
      if (!editedRoadmap) return;
      const newItems = [...editedRoadmap.roadmap.items];
      (newItems[index] as any)[field] = value;
      setEditedRoadmap({ ...editedRoadmap, roadmap: { ...editedRoadmap.roadmap, items: newItems } });
      logEdit(`Updated Roadmap Item: ${field}`);
  };

  const updateRecommendation = (index: number, field: keyof StrategicRecommendation, value: any) => {
      if (!editedRecs) return;
      const newRecs = [...editedRecs.recommendations];
      (newRecs[index] as any)[field] = value;
      setEditedRecs({ ...editedRecs, recommendations: newRecs });
      logEdit(`Edited Recommendation ${index+1}`);
  };

  const deleteRecommendation = (index: number) => {
      if (!editedRecs) return;
      const newRecs = editedRecs.recommendations.filter((_, i) => i !== index);
      setEditedRecs({ ...editedRecs, recommendations: newRecs });
      logEdit(`Deleted Recommendation ${index+1}`);
  };

  const addRecommendation = () => {
      if (!editedRecs) return;
      const newRec: StrategicRecommendation = {
          title: "New Opportunity",
          description: "Describe the strategic opportunity here.",
          impactLevel: "MEDIUM",
          actionItems: ["First step"]
      };
      setEditedRecs({ ...editedRecs, recommendations: [...editedRecs.recommendations, newRec] });
      logEdit(`Added New Recommendation`);
  };

  const updateSlideStructure = (index: number, field: keyof Slide, value: string) => {
      if (!editedStructure) return;
      const newSlides = [...editedStructure.slides];
      (newSlides[index] as any)[field] = value;
      setEditedStructure({ ...editedStructure, slides: newSlides });
      logEdit(`Updated Slide ${index+1}: ${field}`);
  };

  const updateSlideNarrative = (index: number, field: keyof Slide, value: any) => {
      if (!editedNarrative || !editedNarrative.slides) return;
      const newSlides = [...editedNarrative.slides];
      (newSlides[index] as any)[field] = value;
      setEditedNarrative({ ...editedNarrative, slides: newSlides });
      logEdit(`Updated Narrative Slide ${index+1}: ${field}`);
  };

  const updateScriptScene = (index: number, field: keyof ScriptScene, value: any) => {
      if (!editedNarrative || !editedNarrative.videoScript) return;
      const newScript = [...editedNarrative.videoScript];
      (newScript[index] as any)[field] = value;
      setEditedNarrative({ ...editedNarrative, videoScript: newScript });
      logEdit(`Updated Scene ${index+1}: ${field}`);
  };

  const moveSlide = (index: number, direction: 'up' | 'down') => {
      if (!editedStructure) return;
      const newSlides = [...editedStructure.slides];
      if (direction === 'up' && index > 0) {
          [newSlides[index], newSlides[index-1]] = [newSlides[index-1], newSlides[index]];
      } else if (direction === 'down' && index < newSlides.length - 1) {
          [newSlides[index], newSlides[index+1]] = [newSlides[index+1], newSlides[index]];
      }
      newSlides.forEach((s, i) => s.slideNumber = i + 1);
      setEditedStructure({ ...editedStructure, slides: newSlides });
      logEdit("Reordered Slides");
  };

  const addSlide = () => {
      if (!editedStructure) return;
      const newSlide: Slide = {
          slideNumber: editedStructure.slides.length + 1,
          layout: 'CONTENT_SPLIT_RIGHT',
          title: 'New Slide',
          content: [],
          narrative: '',
          speakerNotes: '',
          visualPrompt: '',
          quote: '',
          rationale: 'Added manually',
          style: { backgroundColor: '#000000', headerColor: '#FFFFFF', textColor: '#E2E8F0', accentColor: '#EA00FF' }
      };
      setEditedStructure({ ...editedStructure, slides: [...editedStructure.slides, newSlide] });
      logEdit("Added New Slide");
  };

  const deleteSlide = (index: number) => {
      if (!editedStructure) return;
      const newSlides = editedStructure.slides.filter((_, i) => i !== index).map((s, i) => ({...s, slideNumber: i+1}));
      setEditedStructure({ ...editedStructure, slides: newSlides });
      logEdit(`Deleted Slide ${index+1}`);
  };

  const handleConfirm = () => {
      setIsSubmitting(true);
      let modifiedData = undefined;

      let interventionSummary = "";
      if (feedback) {
          interventionSummary = `User Feedback: "${feedback}"`;
      }

      if (hasEdits) {
          const editCount = editLog.length;
          const specificEdits = editLog.slice(0, 3).join(", ");
          const suffix = editCount > 3 ? `...and ${editCount - 3} more.` : "";

          if (interventionSummary) interventionSummary += " | ";
          interventionSummary += `Manual Interventions: ${specificEdits}${suffix}`;

          if (stage === AnalysisStage.THEMES) modifiedData = { ...data, themes: editedThemes };
          else if (stage === AnalysisStage.PERSONAS) modifiedData = { ...data, personas: editedPersonas };
          else if (stage === AnalysisStage.DECK_STRUCTURE && editedStructure) modifiedData = editedStructure;
          else if (stage === AnalysisStage.NARRATIVE && editedNarrative) modifiedData = editedNarrative;
          else if (stage === AnalysisStage.JOURNEY_MAP && editedJourney) modifiedData = editedJourney;
          else if (stage === AnalysisStage.TECH_ARCH && editedArch) modifiedData = editedArch;
          else if (stage === AnalysisStage.PRD && editedPRD) modifiedData = editedPRD;
          else if (stage === AnalysisStage.ROADMAP && editedRoadmap) modifiedData = editedRoadmap;
          else if (stage === AnalysisStage.RECOMMENDATIONS && editedRecs) modifiedData = editedRecs;
      } else if (!feedback) {
          interventionSummary = "Approved without changes.";
      }

      onApprove(feedback, modifiedData, interventionSummary);
  };

  // --- RENDERERS ---

  const renderIngestion = () => {
      const d = data as StepResult_Ingestion;
      if (!d) return <LoadingView log={currentLog} elapsed={elapsed} />;
      return (
          <div className="space-y-4">
              <div className="bg-[var(--bg-tertiary)] p-4 rounded-lg border border-[var(--border-primary)]">
                  <p className="text-[var(--text-primary)]">{d.summary}</p>
              </div>
              <div className="grid grid-cols-2 gap-4">
                  <div className="bg-[var(--bg-tertiary)] p-4 rounded-lg"><span className="text-xs font-bold text-[var(--text-tertiary)] block">DOCS</span><span className="text-xl font-bold">{d.documents?.length || 0}</span></div>
                  <div className="bg-[var(--bg-tertiary)] p-4 rounded-lg"><span className="text-xs font-bold text-[var(--text-tertiary)] block">CONFIDENCE</span><span className="text-xl font-bold text-green-600">{d.confidenceScore}%</span></div>
              </div>
          </div>
      );
  };

  const renderThemes = () => (
      <div className="space-y-3 max-h-[60vh] overflow-y-auto pr-2">
          {(editedThemes || []).map((theme, idx) => (
              <div key={idx} className={`p-4 rounded-lg border flex gap-4 transition-colors ${theme.status === 'skipped' ? 'opacity-50' : ''}`}>
