                          <p className="text-sm text-[var(--text-secondary)] italic mt-1 line-clamp-1">"{persona.quote}"</p>
                      </div>
                  </div>

                  {expandedPersona === idx && (
                      <div className="p-4 bg-[var(--bg-tertiary)] border-t border-[var(--border-primary)] space-y-4 animate-fade-in">
