    return (
         <div className="max-h-[60vh] overflow-y-auto pr-2 flex flex-col h-full">
             {(hasSlides && hasScript) && (
                 <div className="flex gap-2 mb-4 border-b border-[var(--border-primary)]">
                     <button 
