      try {
          const bioSnippet = p.bio ? p.bio.substring(0, 50) : "";
          const imgPrompt = `Photorealistic portrait of ${p.name}, ${p.role}, ${p.demographics}. Context: ${bioSnippet}. In an environment reflecting their daily behavior. Racially diverse, authentic, candid photography, 85mm lens, cinematic lighting. High resolution.`;
          const url = await generateImage(imgPrompt, "1:1");
          setPersonasData(prev => {
              const updated = [...prev];
              updated[index] = { ...updated[index], imageUrl: url };
              return updated;
          });
