        : (quote ? [{ text: quote, sourceFile: 'Unknown', author: 'Unknown' }] as Citation[] : []);

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in" onClick={onClose}>
            <div className="bg-[var(--modal-bg)] border border-[var(--border-primary)] rounded-xl max-w-2xl w-full shadow-2xl overflow-hidden transform transition-all flex flex-col max-h-[80vh]" onClick={e => e.stopPropagation()}>
                <div className="p-6 border-b border-[var(--border-primary)] flex justify-between items-center bg-[var(--bg-secondary)] shrink-0">
