export const generateImage = async (prompt: string, aspectRatio: string = "16:9", refImageBase64?: string): Promise<string | undefined> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let styleDirectives = "";
    let negativeConstraints = "";

    // Specific Prompt Strategy based on Aspect Ratio context
    if (aspectRatio === "1:1" || aspectRatio === "3:4") {
        // PERSONA / PORTRAIT / SPLIT SLIDE MODE
        styleDirectives = "Style: High-End Editorial Photography with integrated Data UI. 4K, 85mm lens, authentic human subject in a natural, well-lit environment. Clean, modern Augmented Reality (AR) elements (charts, bubbles, stats) are composited into the scene professionally. Sharp focus, high dynamic range.";
        negativeConstraints = "Do not include: illustration, vector art, cartoon, drawing, painting, messy text, misspelled text, gibberish, clutter, neon overload, cyberpunk, gritty, dark mode, low resolution, distorted faces.";
    } else {
        // SCENE / SLIDE MODE (16:9) - MIXED REALITY STYLE
        styleDirectives = "Style: Professional Cinematic Reality with Clean Info-Graphics. High-resolution photography of real-world business or lifestyle settings. Overlay of crisp, modern, flat-design user interface elements floating in 3D space. Data visualization is legible, minimalist, and dynamic. 'Apple-style' clean aesthetic.";
        negativeConstraints = "Do not include: illustration, vector art, cartoon, drawing, painting, messy scribbles, low quality, pixelated, surrealism, sci-fi excess, neon glow, unreadable text.";
    }

    // Force strict adherence to the subject matter
    const finalPrompt = `Depict specifically: ${prompt}. Ensure all visual elements are extremely related to this description. ${styleDirectives} ${negativeConstraints}`; 

    const parts: any[] = [{ text: finalPrompt }];
    if (refImageBase64) {
        const cleanBase64 = refImageBase64.includes('base64,') 
            ? refImageBase64.split('base64,')[1] 
            : refImageBase64;

        parts.unshift({
            inlineData: {
                mimeType: 'image/png',
                data: cleanBase64
            }
        });
        parts[parts.length-1].text += " Maintain strict character consistency with the reference image.";
    }

    const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: parts
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio as any,
          imageSize: "1K"
        }
      }
    }), 3, 2000, "Image Generation");

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        const mimeType = part.inlineData.mimeType || 'image/jpeg';
        return `data:${mimeType};base64,${part.inlineData.data}`;
      }
    }
  } catch (error) {
    console.warn("Image generation failed for prompt:", prompt, error);
    return undefined;
  }
  return undefined;
};

// --- VIDEO GENERATION (VEO 3) ---
export const generateSceneVideo = async (prompt: string, imageBase64?: string): Promise<string | undefined> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        let operation;
        const cleanBase64 = imageBase64?.includes('base64,') ? imageBase64.split('base64,')[1] : imageBase64;

        // Updated Video Prompt for Professional AR Style
        const styleSuffix = ". Cinematic video footage with smooth, tracked infographic overlays. Realistic motion. Data elements (charts, icons, text bubbles) animate cleanly within the physical space. Professional documentary style. 4K resolution. No gibberish text.";
        const fullPrompt = `Animate strictly based on this description: ${prompt}. Ensure visual relevance. ${styleSuffix}`;

        if (cleanBase64) {
             operation = await withRetry(() => ai.models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: fullPrompt,
                image: {
                    imageBytes: cleanBase64,
                    mimeType: 'image/png', 
                },
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
            }), 3, 5000, "Veo Video Generation");
        } else {
             operation = await withRetry(() => ai.models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: fullPrompt,
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
            }), 3, 5000, "Veo Video Generation");
        }

        let retries = 0;
        while (!operation.done && retries < 30) {
            await new Promise(resolve => setTimeout(resolve, 5000));
            operation = await ai.operations.getVideosOperation({operation: operation});
            retries++;
        }

        const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (downloadLink) {
             const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
             const blob = await response.blob();
             return URL.createObjectURL(blob);
        }
    } catch (e) {
        console.error("Veo generation failed", e);
    }
    return undefined;
};

