        const result = await this.executeStep<StepResult_Themes>(prompt, schema, [], onStream);
        if (!result.themes) result.themes = [];
        return result;
    }

    async generatePersonas(themesInput: any | undefined, feedback: string | undefined, onStream: (t: string) => void, onStatus: (s: string) => void): Promise<StepResult_Personas> {
        const prompt = `STEP 3: PERSONAS. Synthesize 2-3 distinct personas. ${feedback ? 'Feedback: ' + feedback : ''} Output JSON.`;
        const schema: Schema = {
            type: Type.OBJECT,
            properties: {
                methodology: { type: Type.STRING },
                personas: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            name: { type: Type.STRING },
                            role: { type: Type.STRING },
                            demographics: { type: Type.STRING },
                            quote: { type: Type.STRING },
                            bio: { type: Type.STRING },
                            fiveWs: { type: Type.OBJECT, properties: { who: {type:Type.STRING}, what: {type:Type.STRING}, whenWhere: {type:Type.STRING}, why: {type:Type.STRING} } },
                            motivations: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { label: { type: Type.STRING }, quote: { type: Type.STRING } } } },
                            tasks: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { label: { type: Type.STRING } } } },
