                className="w-full bg-[var(--input-bg)] border border-[var(--border-primary)] rounded-lg p-3 text-sm focus:border-indigo-500 outline-none resize-none h-20 shadow-sm"
            />
            <div className="flex justify-end gap-3">
                <button onClick={handleConfirm} disabled={isProcessing || isSubmitting} className={`px-6 py-2 rounded-lg font-bold text-sm transition-all shadow-md ${feedback || hasEdits ? 'bg-amber-600 text-white' : 'bg-indigo-600 text-white'} ${isProcessing || isSubmitting ? 'opacity-50 cursor-not-allowed' : ''}`}>
                    {getButtonText()}
                </button>
            </div>
        </div>
    </div>
  );
};

