                slides: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { slideNumber: { type: Type.INTEGER }, layout: { type: Type.STRING }, title: { type: Type.STRING }, content: { type: Type.ARRAY, items: { type: Type.STRING } }, narrative: { type: Type.STRING }, visualPrompt: { type: Type.STRING }, quote: { type: Type.STRING } } } }
            },
            required: ["methodology", "videoScript", "slides"]
        };
        const result = await this.executeStep<StepResult_Narrative>(prompt, schema, [], onStream);
        if (!result.videoScript) result.videoScript = [];
        if (!result.slides) result.slides = [];

        const slidesWithStyle = (result.slides).map(slide => ({ ...slide, style: { ...DEFAULT_STYLE } }));
